package code.producer_consumer;

public class BlockingQueueDemo {

    public static void test1() throws InterruptedException {
        final BockingQueue<Integer> q = new BlockingQueueWithSemaphoreImpl<>(5);

        Thread t1 = new Thread(() -> {
            for (int i = 0; i < 50; ++i) {
                try {
                    q.enqueue(i);
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                }
                System.out.println("added: " + i);
            }
        });

        Thread t2 = new Thread(() -> {
            int item;

            for (int i = 0; i < 25; ++i) {
                try {
                    item = q.dequeue();
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                }
                System.out.println("removed: " + item);
            }
        });


        Thread t3 = new Thread(() -> {
            for (int i = 0; i < 25; ++i) {
                int item;
                try {
                    item = q.dequeue();
                } catch (InterruptedException e) {
                    throw new RuntimeException(e);
                }
                System.out.println("removed: " + item);
            }
        });

        t1.start();
        Thread.sleep(4000);
        t2.start();
        t3.start();

        t2.join();
        t1.join();
        t3.join();
    }


    public static void main(String[] args) throws InterruptedException {
        test1();
    }
}

package code.producer_consumer;

public class BlockingQueueMonitorImpl<T> implements BockingQueue<T>{

    T[] array;
    int size = 0;
    int capacity;
    int head = 0;
    int tail = 0;

    BlockingQueueMonitorImpl(int capacity){
        this.capacity = capacity;
        array = (T[]) new Object[capacity];
    }

        @Override
    public synchronized void enqueue(T item) throws InterruptedException {
        while(size == capacity){
            wait();
        }
        if(tail == capacity){
            tail = 0;
        }
        array[tail] = item;
        size++;
        tail++;
        notifyAll();
    }

    @Override
    public synchronized T dequeue() throws InterruptedException {
        while(size == 0){
            wait();
        }
        T item;

        if(head == capacity){
            head = 0;
        }
        item = array[head];
        array[head] = null;
        head++;
        size--;
        notifyAll();
        return item;
    }

}

package code.producer_consumer;


import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class BlockingQueueWithLockImpl<T> implements BockingQueue<T>{

    T[] array;
    int size = 0;
    int capacity;
    int head = 0;
    int tail = 0;

    Lock lock = new ReentrantLock();

    BlockingQueueWithLockImpl(int capacity){
        this.capacity = capacity;
        array = (T[]) new Object[capacity];
    }

    public void enqueue(T item) throws InterruptedException {
        lock.lock();

        while(size == capacity){
            lock.unlock(); //release the lock to give other thread a chance.

            lock.lock(); // require the lock before checking the condition.
        }

        if(tail == capacity){
            tail = 0;
        }
        array[tail] = item;
        size++;
        tail++;
        lock.unlock();
    }

    public  T dequeue() throws InterruptedException {
        lock.lock();

        while(size == 0){
            lock.unlock();
            lock.lock();
        }
        T item;

        if(head == capacity){
            head = 0;
        }
        item = array[head];
        array[head] = null;
        head++;
        size--;
        lock.unlock();
        return item;
    }
}

