package code.behavioral.chain_of_responsibilty;

import java.util.List;
import java.util.Objects;

public final class ChainOfResponsibilityDemo {
    private ChainOfResponsibilityDemo() {
    }

    public record PurchaseRequest(boolean authenticated, String role, int amount) {
        public PurchaseRequest {
            Objects.requireNonNull(role, "role");
            if (amount <= 0) {
                throw new IllegalArgumentException("amount must be positive");
            }
        }
    }

    private abstract static class Handler {
        private Handler next;

        final Handler linkWith(Handler nextHandler) {
            next = Objects.requireNonNull(nextHandler, "nextHandler");
            return nextHandler;
        }

        final boolean handle(PurchaseRequest request) {
            if (!check(request)) {
                return false;
            }
            return next == null || next.handle(request);
        }

        protected abstract boolean check(PurchaseRequest request);
    }

    private static final class AuthenticationHandler extends Handler {
        @Override
        protected boolean check(PurchaseRequest request) {
            return request.authenticated();
        }
    }

    private static final class RoleHandler extends Handler {
        @Override
        protected boolean check(PurchaseRequest request) {
            return "BUYER".equals(request.role());
        }
    }

    private static final class SpendingLimitHandler extends Handler {
        private final int limit;

        private SpendingLimitHandler(int limit) {
            this.limit = limit;
        }

        @Override
        protected boolean check(PurchaseRequest request) {
            return request.amount() <= limit;
        }
    }

    public static void main(String[] args) {
        Handler chain = new AuthenticationHandler();
        chain.linkWith(new RoleHandler()).linkWith(new SpendingLimitHandler(1_000));

        List<PurchaseRequest> requests = List.of(
                new PurchaseRequest(true, "BUYER", 750),
                new PurchaseRequest(false, "BUYER", 100),
                new PurchaseRequest(true, "BUYER", 1_500));

        requests.forEach(request ->
                System.out.printf("%s -> %s%n", request, chain.handle(request) ? "accepted" : "rejected"));
    }
}

package code.behavioral.command;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Objects;

public final class CommandDemo {
    private CommandDemo() {
    }

    private interface Command {
        void execute();

        void undo();
    }

    private static final class TextEditor {
        private final StringBuilder text = new StringBuilder();

        void append(String value) {
            text.append(value);
        }

        void truncate(int length) {
            text.setLength(length);
        }

        int length() {
            return text.length();
        }

        String text() {
            return text.toString();
        }
    }

    private static final class AppendTextCommand implements Command {
        private final TextEditor editor;
        private final String value;
        private int previousLength;
        private boolean executed;

        private AppendTextCommand(TextEditor editor, String value) {
            this.editor = Objects.requireNonNull(editor, "editor");
            this.value = Objects.requireNonNull(value, "value");
        }

        @Override
        public void execute() {
            if (executed) {
                throw new IllegalStateException("command is already executed");
            }
            previousLength = editor.length();
            editor.append(value);
            executed = true;
        }

        @Override
        public void undo() {
            if (!executed) {
                throw new IllegalStateException("command is not executed");
            }
            editor.truncate(previousLength);
            executed = false;
        }
    }

    private static final class CommandHistory {
        private final Deque<Command> executed = new ArrayDeque<>();

        void execute(Command command) {
            command.execute();
            executed.push(command);
        }

        void undoLast() {
            if (!executed.isEmpty()) {
                executed.pop().undo();
            }
        }
    }

    public static void main(String[] args) {
        TextEditor editor = new TextEditor();
        CommandHistory history = new CommandHistory();

        history.execute(new AppendTextCommand(editor, "Design "));
        history.execute(new AppendTextCommand(editor, "Patterns"));
        System.out.println(editor.text());

        history.undoLast();
        System.out.println(editor.text());
    }
}

package code.behavioral.interpretor;

import java.util.Map;
import java.util.Objects;

public final class InterpreterDemo {
    private InterpreterDemo() {
    }

    private sealed interface Expression permits Variable, And, Or, Not {
        boolean interpret(Map<String, Boolean> context);
    }

    private record Variable(String name) implements Expression {
        private Variable {
            Objects.requireNonNull(name, "name");
        }

        @Override
        public boolean interpret(Map<String, Boolean> context) {
            return context.getOrDefault(name, false);
        }
    }

    private record And(Expression left, Expression right) implements Expression {
        @Override
        public boolean interpret(Map<String, Boolean> context) {
            return left.interpret(context) && right.interpret(context);
        }
    }

    private record Or(Expression left, Expression right) implements Expression {
        @Override
        public boolean interpret(Map<String, Boolean> context) {
            return left.interpret(context) || right.interpret(context);
        }
    }

    private record Not(Expression expression) implements Expression {
        @Override
        public boolean interpret(Map<String, Boolean> context) {
            return !expression.interpret(context);
        }
    }

    public static void main(String[] args) {
        Expression canPublish = new And(
                new Variable("authenticated"),
                new Or(new Variable("editor"), new Variable("admin")));

        Map<String, Boolean> editor = Map.of("authenticated", true, "editor", true);
        Map<String, Boolean> guest = Map.of("authenticated", true, "editor", false, "admin", false);

        System.out.println("editor can publish: " + canPublish.interpret(editor));
        System.out.println("guest denied: " + new Not(canPublish).interpret(guest));
    }
}

package code.behavioral.iterator;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;

public final class IteratorDemo {
    private IteratorDemo() {
    }

    private static final class Playlist implements Iterable<String> {
        private final List<String> songs = new ArrayList<>();

        Playlist add(String song) {
            songs.add(song);
            return this;
        }

        @Override
        public Iterator<String> iterator() {
            return new PlaylistIterator(List.copyOf(songs));
        }
    }

    private static final class PlaylistIterator implements Iterator<String> {
        private final List<String> snapshot;
        private int index;

        private PlaylistIterator(List<String> snapshot) {
            this.snapshot = snapshot;
        }

        @Override
        public boolean hasNext() {
            return index < snapshot.size();
        }

        @Override
        public String next() {
            if (!hasNext()) {
                throw new NoSuchElementException("playlist exhausted");
            }
            return snapshot.get(index++);
        }
    }

    public static void main(String[] args) {
        Playlist playlist = new Playlist().add("Intro").add("Bridge").add("Finale");
        for (String song : playlist) {
            System.out.println(song);
        }
    }
}

