            throw new IllegalArgumentException("amount must be positive");
        }
        this.amountInCents = amountInCents;
    }

    public final void pay() {
        validate();
        debit();
        sendMoney();
        notifyCompletion();
    }

    protected void validate() {
        System.out.println("validated " + amountInCents + " cents");
    }

