// VIOLATION: Liskov Substitution Principle
// Square cannot be substituted for Rectangle without breaking behavior

class Rectangle {
    protected int width, height;

    public void setWidth(int width) {
        this.width = width;
    }

    public void setHeight(int height) {
        this.height = height;
    }

    public int getArea() {
        return width * height;
    }
}

// This breaks LSP - Square has different behavior than Rectangle
class Square extends Rectangle {
    @Override
    public void setWidth(int width) {
        super.setWidth(width);
        super.setHeight(width); // Breaking change!
    }

    @Override
    public void setHeight(int height) {
        super.setWidth(height); // Breaking change!
        super.setHeight(height);
    }
}

public class AreaCalculator {
    public static void main(String[] args) {
        Rectangle rect = new Rectangle();
        rect.setWidth(5);
        rect.setHeight(10);
        System.out.println("Rectangle area: " + rect.getArea()); // 50

        // This should work the same way, but it doesn't!
        Rectangle square = new Square();
        square.setWidth(5);
        square.setHeight(10);
        System.out.println("Square area: " + square.getArea()); // 100 (unexpected!)
    }
}

// FIXED: Following Liskov Substitution Principle
// Use composition instead of inheritance for different behaviors

interface Shape {
    double getArea();
}

class Rectangle implements Shape {
    protected double width, height;

    public Rectangle(double width, double height) {
        this.width = width;
        this.height = height;
    }

    public void setWidth(double width) {
        this.width = width;
    }

    public void setHeight(double height) {
        this.height = height;
    }

    @Override
    public double getArea() {
        return width * height;
    }
}

class Square implements Shape {
    private double side;

    public Square(double side) {
        this.side = side;
    }

    public void setSide(double side) {
        this.side = side;
    }

    @Override
    public double getArea() {
        return side * side;
    }
}

// Now both can be used interchangeably without breaking behavior
class AreaCalculator {
    public static void main(String[] args) {
        Shape rect = new Rectangle(5, 10);
        Shape square = new Square(5);

        System.out.println("Rectangle area: " + rect.getArea()); // 50
        System.out.println("Square area: " + square.getArea());   // 25

        // Both work as expected - LSP satisfied!
        calculateAndPrintArea(rect);
        calculateAndPrintArea(square);
    }

    private static void calculateAndPrintArea(Shape shape) {
        System.out.println("Shape area: " + shape.getArea());
    }
}

// VIOLATION: Open-Closed Principle
// This class needs to be modified every time a new shape is added

public class AreaCalculator {
    public double calculateArea(Object shape) {
        if (shape instanceof Rectangle) {
            Rectangle rect = (Rectangle) shape;
            return rect.width * rect.height;
        } else if (shape instanceof Circle) {
            Circle circle = (Circle) shape;
            return Math.PI * circle.radius * circle.radius;
        }
        // Need to add more conditions for new shapes...
        return 0;
    }
}

