import java.util.Optional;

public class CacheImpl<Key, Value> implements ICache<Key, Value>{

    IStorage storage;
    IEvictionPolicy evictionPolicy;

    CacheImpl(IStorage storage, IEvictionPolicy evictionPolicy){
        this.storage = storage;
        this.evictionPolicy = evictionPolicy;
    }

    @Override
    public Value get(Key key) throws KeyNotFoundException {
        evictionPolicy.acessedKey(key);
        return (Value) storage.get(key);
    }

    @Override
    public void put(Key key, Value value) {
        try{
            storage.add(key, value);
            evictionPolicy.acessedKey(key);
        } catch (StorageFullException e) {
            Optional<Key> optionalKey = evictionPolicy.evictKey();
            if(!optionalKey.isPresent()){
                throw new RuntimeException();
            }
            try {
                storage.delete(key);
                put(key, value);
            } catch (KeyNotFoundException ex) {
                throw new RuntimeException(ex);
            }
        }
    }
}

package code.algorithms;

public class DoublyLinkedList<T> {
    DoublyLinkedListNode<T> head;
    DoublyLinkedListNode<T> tail;

    public void addInBegin(T value){
        DoublyLinkedListNode<T> doublyLinkedListNode = new DoublyLinkedListNode<>(value);
        doublyLinkedListNode.next = head;
        head = doublyLinkedListNode;

        // adding first item
        if(tail == null){
            tail = doublyLinkedListNode;
        }
    }

    public void deleteNode(DoublyLinkedListNode<T> node){
        if(node.prev != null){
            node.prev.next = node.next;
        }
        else{
            head = head.next;
        }

        if(node.next != null){
            node.next.prev = node.prev;
        }
        else{
            tail = tail.prev;
        }
    }

    public DoublyLinkedListNode<T> getHead() {
        return head;
    }

    public DoublyLinkedListNode<T> getTail() {
        return tail;
    }

    public boolean isEmpty(){
        return head == null;
    }
}

