    }
}

import java.util.HashMap;
import java.util.Map;

public class HashMapBasedStorage<Key, Value> implements IStorage<Key, Value> {

    private Map<Key, Value> mp;
    private int maxCapacity;
    private int currentSize;

    HashMapBasedStorage(int N){
        maxCapacity = N;
        currentSize = 0;
        mp = new HashMap<>();
    }

    @Override
    public Value get(Key key) throws KeyNotFoundException {
        if(mp.containsKey(key)){
            return mp.get(key);
        }
        else{
            throw new KeyNotFoundException();
        }
    }

    @Override
    public void add(Key key, Value value) throws StorageFullException {
        if(currentSize == maxCapacity){
            throw new StorageFullException();
        }
        else{
            if(!mp.containsKey(key)){
                currentSize++;
            }
            mp.put(key, value);
        }
    }

    @Override
    public void delete(Key key) throws KeyNotFoundException {
        if(!mp.containsKey(key)){
            throw new KeyNotFoundException();
        }
        mp.remove(key);
    }

    @Override
    public boolean isFull() {
        return maxCapacity == currentSize;
    }
}

public interface ICache<Key, Value> {
    Value get(Key key) throws KeyNotFoundException;
    void put(Key key, Value value);
}

import java.util.Optional;

public interface IEvictionPolicy<Key> {

    Optional<Key> evictKey();
    void acessedKey(Key key);
}

public interface IStorage<Key, Value> {
    void delete(Key key) throws KeyNotFoundException;
    Value get(Key key) throws KeyNotFoundException;
    void add(Key key, Value value) throws StorageFullException;
    boolean isFull();
}

import java.util.HashMap;
import java.util.Map;
import java.util.Optional;


public class LRUEvictionPolicy<Key> implements IEvictionPolicy<Key> {

    DoublyLinkedList<Key> dll;
    Map<Key, DoublyLinkedListNode<Key>> mp = new HashMap<>();


    @Override
    public Optional evictKey() {
        if(dll.isEmpty()) return Optional.empty();
        DoublyLinkedListNode doublyLinkedListNode = dll.removeFirstNode();
        return Optional.of(doublyLinkedListNode.getValue());
    }

    @Override
    public void acessedKey(Key key) {
        if(mp.containsKey(key)){
            mp.remove(key);
        }
        DoublyLinkedListNode doublyLinkedListNode = new DoublyLinkedListNode(key);
        dll.insertInEnd(doublyLinkedListNode);
        mp.put(key, doublyLinkedListNode);
    }
}

