package com.example.lld.inventory_reservation_service.service;

import com.example.lld.inventory_reservation_service.exception.InsufficientInventoryException;
import com.example.lld.inventory_reservation_service.model.InventoryBalance;
import com.example.lld.inventory_reservation_service.model.ReservationLine;
import com.example.lld.inventory_reservation_service.port.AllocationStrategy;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** Deterministic SKU/location first-fit policy; it never mutates service state. */
public final class FirstFitAllocationStrategy implements AllocationStrategy {
    @Override
    public List<ReservationLine> allocate(
            Map<String, Integer> requestedQuantities,
            List<InventoryBalance> balances) {
        List<InventoryBalance> orderedBalances = balances.stream()
                .sorted(Comparator.comparing(InventoryBalance::key))
                .toList();
        List<ReservationLine> result = new ArrayList<>();
        for (Map.Entry<String, Integer> request
                : new TreeMap<>(requestedQuantities).entrySet()) {
            int remaining = request.getValue();
            int totalAvailable = 0;
            for (InventoryBalance balance : orderedBalances) {
                if (!balance.key().sku().equals(request.getKey())) {
                    continue;
                }
                totalAvailable = Math.addExact(totalAvailable, balance.available());
                int allocated = Math.min(remaining, balance.available());
                if (allocated > 0) {
                    result.add(new ReservationLine(
                            request.getKey(), balance.key().location(), allocated));
                    remaining -= allocated;
                }
                if (remaining == 0) {
                    break;
                }
            }
            if (remaining > 0) {
                throw new InsufficientInventoryException(
                        request.getKey(), request.getValue(), totalAvailable);
            }
        }
        return List.copyOf(result);
    }
}

package com.example.lld.inventory_reservation_service.service;

import com.example.lld.inventory_reservation_service.exception.IdempotencyConflictException;
import com.example.lld.inventory_reservation_service.exception.InvalidReservationStateException;
import com.example.lld.inventory_reservation_service.exception.ReservationExpiredException;
import com.example.lld.inventory_reservation_service.exception.ReservationNotFoundException;
import com.example.lld.inventory_reservation_service.model.InventoryBalance;
import com.example.lld.inventory_reservation_service.model.InventoryKey;
import com.example.lld.inventory_reservation_service.model.Reservation;
import com.example.lld.inventory_reservation_service.model.ReservationLine;
import com.example.lld.inventory_reservation_service.model.ReservationStatus;
import com.example.lld.inventory_reservation_service.port.AllocationStrategy;
import com.example.lld.inventory_reservation_service.port.IdGenerator;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.TreeMap;
import java.util.concurrent.locks.ReentrantLock;

/**
 * Thread-safe in-memory reference implementation. One fair lock is the transaction
 * boundary, making multi-SKU checks and counter changes all-or-nothing and giving a
 * deterministic winner to confirmation, release, and expiry.
 */
public final class InventoryReservationService {
    private final Clock clock;
    private final IdGenerator idGenerator;
    private final AllocationStrategy allocationStrategy;
    private final ReentrantLock transactionLock = new ReentrantLock(true);
    private final Map<InventoryKey, BalanceState> balances = new HashMap<>();
    private final Map<String, Reservation> reservations = new HashMap<>();
    private final Map<String, IdempotencyEntry> completedCommands = new HashMap<>();

    public InventoryReservationService(
            Clock clock,
            IdGenerator idGenerator,
            AllocationStrategy allocationStrategy) {
        this.clock = Objects.requireNonNull(clock, "clock");
        this.idGenerator = Objects.requireNonNull(idGenerator, "idGenerator");
        this.allocationStrategy = Objects.requireNonNull(allocationStrategy, "allocationStrategy");
    }

    public void addStock(String sku, String location, int quantity) {
        if (quantity <= 0) {
            throw new IllegalArgumentException("quantity must be positive");
        }
        InventoryKey key = new InventoryKey(sku, location);
        transactionLock.lock();
        try {
            BalanceState state = balances.computeIfAbsent(key, ignored -> new BalanceState());
            state.onHand = Math.addExact(state.onHand, quantity);
        } finally {
            transactionLock.unlock();
        }
    }

    public Reservation reserve(
            String idempotencyKey,
            Map<String, Integer> requestedQuantities,
            Duration timeToLive) {
        requireKey(idempotencyKey);
        if (timeToLive == null || timeToLive.isZero() || timeToLive.isNegative()) {
            throw new IllegalArgumentException("timeToLive must be positive");
        }
        Map<String, Integer> requested = validatedRequest(requestedQuantities);
        String fingerprint = new TreeMap<>(requested) + "|ttl=" + timeToLive;
        transactionLock.lock();
        try {
            Reservation duplicate = duplicateResult("reserve", idempotencyKey, fingerprint);
            if (duplicate != null) {
                return duplicate;
            }
            Instant now = clock.instant();
            expireDueLocked(now);
            List<ReservationLine> allocation = allocationStrategy.allocate(
                    requested, balanceSnapshots());
            Map<InventoryKey, Integer> byBalance = validateAllocation(requested, allocation);

            // No counter changes occur before the complete allocation has been validated.
            for (Map.Entry<InventoryKey, Integer> entry : byBalance.entrySet()) {
                BalanceState balance = balances.get(entry.getKey());
                balance.reserved = Math.addExact(balance.reserved, entry.getValue());
            }
            Reservation reservation = Reservation.active(
                    idGenerator.nextId(), allocation, now, now.plus(timeToLive));
            reservations.put(reservation.reservationId(), reservation);
            remember("reserve", idempotencyKey, fingerprint, reservation);
            return reservation;
        } finally {
            transactionLock.unlock();
        }
    }

    public Reservation confirm(String idempotencyKey, String reservationId) {
        requireKey(idempotencyKey);
        String fingerprint = requireText(reservationId, "reservationId");
        transactionLock.lock();
        try {
            Reservation duplicate = duplicateResult("confirm", idempotencyKey, fingerprint);
            if (duplicate != null) {
                return duplicate;
            }
            Reservation current = requireReservation(reservationId);
            if (current.status() == ReservationStatus.CONFIRMED) {
                remember("confirm", idempotencyKey, fingerprint, current);
                return current;
            }
            if (current.status() != ReservationStatus.ACTIVE) {
                throw invalidTransition(current, "confirm");
            }
            if (current.isDueAt(clock.instant())) {
                Reservation expired = expire(current);
                reservations.put(reservationId, expired);
                throw new ReservationExpiredException(reservationId);
            }
            for (ReservationLine line : current.lines()) {
                BalanceState balance = balances.get(line.inventoryKey());
                balance.reserved -= line.quantity();
                balance.onHand -= line.quantity();
            }
            Reservation confirmed = current.transitionTo(ReservationStatus.CONFIRMED);
            reservations.put(reservationId, confirmed);
            remember("confirm", idempotencyKey, fingerprint, confirmed);
            return confirmed;
        } finally {
            transactionLock.unlock();
        }
    }

    public Reservation release(String idempotencyKey, String reservationId) {
        requireKey(idempotencyKey);
        String fingerprint = requireText(reservationId, "reservationId");
        transactionLock.lock();
        try {
            Reservation duplicate = duplicateResult("release", idempotencyKey, fingerprint);
            if (duplicate != null) {
                return duplicate;
            }
            Reservation current = requireReservation(reservationId);
            if (current.status() == ReservationStatus.RELEASED) {
                remember("release", idempotencyKey, fingerprint, current);
                return current;
            }
            if (current.status() != ReservationStatus.ACTIVE) {
                throw invalidTransition(current, "release");
            }
            if (current.isDueAt(clock.instant())) {
                Reservation expired = expire(current);
                reservations.put(reservationId, expired);
                throw invalidTransition(expired, "release");
            }
            releaseHeldCounters(current);
            Reservation released = current.transitionTo(ReservationStatus.RELEASED);
            reservations.put(reservationId, released);
            remember("release", idempotencyKey, fingerprint, released);
            return released;
        } finally {
            transactionLock.unlock();
        }
    }

    /** Expires every reservation whose expiry is less than or equal to the injected clock. */
    public int expireDueReservations() {
        transactionLock.lock();
        try {
            return expireDueLocked(clock.instant());
        } finally {
            transactionLock.unlock();
        }
    }

    public Reservation getReservation(String reservationId) {
        transactionLock.lock();
        try {
            expireDueLocked(clock.instant());
            return requireReservation(reservationId);
        } finally {
            transactionLock.unlock();
        }
    }

    public InventoryBalance getBalance(String sku, String location) {
        InventoryKey key = new InventoryKey(sku, location);
        transactionLock.lock();
        try {
            expireDueLocked(clock.instant());
            BalanceState state = balances.get(key);
            return state == null
                    ? new InventoryBalance(key, 0, 0)
                    : state.snapshot(key);
        } finally {
            transactionLock.unlock();
        }
    }

    public List<InventoryBalance> balances() {
        transactionLock.lock();
        try {
            expireDueLocked(clock.instant());
            return balanceSnapshots();
        } finally {
            transactionLock.unlock();
        }
    }

    private Map<InventoryKey, Integer> validateAllocation(
            Map<String, Integer> requested,
            List<ReservationLine> allocation) {
        Map<String, Integer> bySku = new HashMap<>();
        Map<InventoryKey, Integer> byBalance = new LinkedHashMap<>();
        for (ReservationLine line : allocation) {
            if (!requested.containsKey(line.sku())) {
                throw new IllegalStateException(
                        "Allocation strategy returned unrequested SKU " + line.sku());
            }
            bySku.merge(line.sku(), line.quantity(), Math::addExact);
            byBalance.merge(line.inventoryKey(), line.quantity(), Math::addExact);
        }
        if (!requested.equals(new TreeMap<>(bySku))) {
            throw new IllegalStateException(
                    "Allocation strategy must allocate every requested quantity exactly");
        }
        for (Map.Entry<InventoryKey, Integer> entry : byBalance.entrySet()) {
            BalanceState state = balances.get(entry.getKey());
            if (state == null || entry.getValue() > state.available()) {
                throw new IllegalStateException(
                        "Allocation strategy exceeded availability for " + entry.getKey());
            }
        }
        return byBalance;
    }

    private int expireDueLocked(Instant now) {
        List<String> dueIds = reservations.values().stream()
                .filter(reservation -> reservation.status() == ReservationStatus.ACTIVE)
                .filter(reservation -> reservation.isDueAt(now))
                .map(Reservation::reservationId)
                .toList();
        for (String reservationId : dueIds) {
            Reservation current = reservations.get(reservationId);
            reservations.put(reservationId, expire(current));
        }
        return dueIds.size();
    }

    private Reservation expire(Reservation reservation) {
        releaseHeldCounters(reservation);
        return reservation.transitionTo(ReservationStatus.EXPIRED);
    }

    private void releaseHeldCounters(Reservation reservation) {
        for (ReservationLine line : reservation.lines()) {
            BalanceState balance = balances.get(line.inventoryKey());
            balance.reserved -= line.quantity();
            if (balance.reserved < 0) {
                throw new IllegalStateException("reserved inventory became negative");
            }
        }
    }

    private List<InventoryBalance> balanceSnapshots() {
        List<InventoryBalance> result = new ArrayList<>(balances.size());
        for (Map.Entry<InventoryKey, BalanceState> entry : balances.entrySet()) {
            result.add(entry.getValue().snapshot(entry.getKey()));
        }
        result.sort((left, right) -> left.key().compareTo(right.key()));
        return List.copyOf(result);
    }

    private Reservation requireReservation(String reservationId) {
        Reservation reservation = reservations.get(reservationId);
        if (reservation == null) {
            throw new ReservationNotFoundException(reservationId);
        }
        return reservation;
    }

    private Reservation duplicateResult(String operation, String key, String fingerprint) {
        IdempotencyEntry entry = completedCommands.get(operation + ':' + key);
        if (entry == null) {
            return null;
        }
        if (!entry.fingerprint().equals(fingerprint)) {
            throw new IdempotencyConflictException(key);
        }
        return entry.result();
    }

    private void remember(
            String operation, String key, String fingerprint, Reservation result) {
        completedCommands.put(operation + ':' + key, new IdempotencyEntry(fingerprint, result));
    }

    private static InvalidReservationStateException invalidTransition(
            Reservation reservation, String action) {
        return new InvalidReservationStateException(
                "Cannot " + action + " reservation " + reservation.reservationId()
                        + " in " + reservation.status());
    }

    private static Map<String, Integer> validatedRequest(Map<String, Integer> request) {
        if (request == null || request.isEmpty()) {
            throw new IllegalArgumentException("at least one SKU quantity is required");
        }
        Map<String, Integer> result = new TreeMap<>();
        for (Map.Entry<String, Integer> entry : request.entrySet()) {
            String sku = requireText(entry.getKey(), "sku");
            Integer quantity = entry.getValue();
            if (quantity == null || quantity <= 0) {
                throw new IllegalArgumentException("quantity must be positive for " + sku);
            }
            result.put(sku, quantity);
        }
        return Map.copyOf(result);
    }

    private static void requireKey(String key) {
        requireText(key, "idempotencyKey");
    }

    private static String requireText(String value, String field) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(field + " must not be blank");
        }
        return value;
    }

    private static final class BalanceState {
        private int onHand;
        private int reserved;

        private int available() {
            return onHand - reserved;
        }

        private InventoryBalance snapshot(InventoryKey key) {
            return new InventoryBalance(key, onHand, reserved);
        }
    }

    private record IdempotencyEntry(String fingerprint, Reservation result) {
    }
}

"""Interview-sized inventory core with atomic holds and precise expiry.

Ordered per-inventory-key locks model the storage transaction.  A real repository
must atomically persist balances, reservation, idempotency receipt, and outbox row.
"""

from __future__ import annotations

from contextlib import contextmanager
from dataclasses import dataclass, replace
from datetime import datetime, timedelta
from enum import Enum
from threading import RLock
from typing import Dict, Iterator, Mapping, Optional, Protocol, Tuple


class InventoryError(Exception):
    pass


class InsufficientInventory(InventoryError):
    pass


class InvalidAllocation(InventoryError):
    pass


class IdempotencyConflict(InventoryError):
    pass


@dataclass(frozen=True, order=True)
class InventoryKey:
    sku: str
    location_id: str

    def __post_init__(self) -> None:
        if not self.sku.strip() or not self.location_id.strip():
            raise ValueError("SKU and location must not be blank")


@dataclass(frozen=True)
class InventoryBalance:
    key: InventoryKey
    on_hand: int
    reserved: int
    version: int

    def __post_init__(self) -> None:
        if self.on_hand < 0 or self.reserved < 0 or self.reserved > self.on_hand:
            raise ValueError("balance must satisfy 0 <= reserved <= on_hand")

    @property
    def available(self) -> int:
        return self.on_hand - self.reserved


@dataclass
class _Balance:
    on_hand: int
    reserved: int = 0
    version: int = 1

    def snapshot(self, key: InventoryKey) -> InventoryBalance:
        return InventoryBalance(key, self.on_hand, self.reserved, self.version)

    def hold(self, quantity: int) -> None:
        if quantity <= 0 or quantity > self.on_hand - self.reserved:
            raise InsufficientInventory("not enough available inventory")
        self.reserved += quantity
        self.version += 1

    def finish(self, quantity: int, consume: bool) -> None:
        if quantity <= 0 or quantity > self.reserved:
            raise AssertionError("reservation counters are inconsistent")
        self.reserved -= quantity
        if consume:
            self.on_hand -= quantity
        self.version += 1


@dataclass(frozen=True)
class Allocation:
    key: InventoryKey
    quantity: int

    def __post_init__(self) -> None:
        if self.quantity <= 0:
            raise ValueError("allocation quantity must be positive")


class ReservationStatus(Enum):
    ACTIVE = "ACTIVE"
    CONFIRMED = "CONFIRMED"
    RELEASED = "RELEASED"
    EXPIRED = "EXPIRED"


@dataclass(frozen=True)
class Reservation:
    reservation_id: str
    requested: Tuple[Tuple[str, int], ...]
    allocations: Tuple[Allocation, ...]
    created_at: datetime
    expires_at: datetime
    status: ReservationStatus = ReservationStatus.ACTIVE
    version: int = 1

    def __post_init__(self) -> None:
        if not self.reservation_id or not self.requested or not self.allocations:
            raise ValueError("reservation ID, request, and allocations are required")
        if self.expires_at <= self.created_at:
            raise ValueError("reservation expiry must be after creation")

    def is_due(self, now: datetime) -> bool:
        return now >= self.expires_at

    def terminal(self, status: ReservationStatus) -> "Reservation":
        if self.status is not ReservationStatus.ACTIVE or status is ReservationStatus.ACTIVE:
            raise InventoryError("invalid reservation transition")
        return replace(self, status=status, version=self.version + 1)


class AllocationStrategy(Protocol):
    def allocate(
        self, requested: Mapping[str, int], balances: Tuple[InventoryBalance, ...]
    ) -> Tuple[Allocation, ...]:
        """Return a pure proposal; the service owns validation and mutation."""


class FirstFitAllocationStrategy:
    """Deterministic first-fit by SKU, then location."""

    def allocate(
        self, requested: Mapping[str, int], balances: Tuple[InventoryBalance, ...]
    ) -> Tuple[Allocation, ...]:
        by_sku: Dict[str, list] = {}
        for balance in sorted(balances, key=lambda item: item.key):
            by_sku.setdefault(balance.key.sku, []).append(balance)
        proposed = []
        for sku, wanted in sorted(requested.items()):
            remaining = wanted
            for balance in by_sku.get(sku, []):
                quantity = min(remaining, balance.available)
                if quantity:
                    proposed.append(Allocation(balance.key, quantity))
                    remaining -= quantity
                if not remaining:
                    break
            if remaining:
                raise InsufficientInventory(
                    "SKU {} is short by {} unit(s)".format(sku, remaining)
                )
        return tuple(proposed)


class Clock(Protocol):
    def now(self) -> datetime:
        ...


class ReservationIds(Protocol):
    def next_id(self) -> str:
        ...


class CommandOutcome(Enum):
    APPLIED = "APPLIED"
    REJECTED = "REJECTED"
    EXPIRED = "EXPIRED"
    CONFLICT = "CONFLICT"


@dataclass(frozen=True)
class CommandResult:
    outcome: CommandOutcome
    reservation: Optional[Reservation]
    message: str = ""


@dataclass(frozen=True)
class _Receipt:
    fingerprint: Tuple[object, ...]
    result: CommandResult


class InventoryReservationService:
    """Locks every touched key in sorted order before check-and-mutate."""

    def __init__(
        self,
        clock: Clock,
        reservation_ids: ReservationIds,
        strategy: Optional[AllocationStrategy] = None,
    ) -> None:
        self._clock, self._ids = clock, reservation_ids
        self._strategy = strategy or FirstFitAllocationStrategy()
        self._balances: Dict[InventoryKey, _Balance] = {}
        self._reservations: Dict[str, Reservation] = {}
        self._receipts: Dict[Tuple[str, str], _Receipt] = {}
        self._key_locks: Dict[InventoryKey, RLock] = {}
        self._command_locks: Dict[Tuple[str, str], RLock] = {}
        self._meta_lock = RLock()

    def set_on_hand(self, key: InventoryKey, quantity: int) -> InventoryBalance:
        """Trusted adjustment port; active holds may not be invalidated."""
        if quantity < 0:
            raise ValueError("on-hand must not be negative")
        with self._lock_keys((key,)):
            with self._meta_lock:
                balance = self._balances.get(key)
                if balance is None:
                    balance = self._balances[key] = _Balance(quantity)
                    created = True
                else:
                    created = False
            if not created:
                if quantity < balance.reserved:
                    raise InventoryError("on-hand cannot fall below reserved")
                balance.on_hand, balance.version = quantity, balance.version + 1
            return balance.snapshot(key)

    def reserve(
        self, key: str, requested: Mapping[str, int], ttl: timedelta
    ) -> CommandResult:
        canonical = self._canonical_request(requested)
        if ttl <= timedelta(0):
            raise ValueError("TTL must be positive")
        scope, fingerprint = self._scope("reserve", key), (canonical, ttl)
        with self._command_lock(scope):
            replay = self._replay(scope, fingerprint)
            if replay:
                return replay
            requested_by_sku = dict(canonical)
            with self._meta_lock:
                candidates = tuple(sorted(
                    inventory_key for inventory_key in self._balances
                    if inventory_key.sku in requested_by_sku
                ))

            # Allocation is only a proposal; no counter moves until every SKU fits.
            with self._lock_keys(candidates):
                snapshots = tuple(
                    self._balances[inventory_key].snapshot(inventory_key)
                    for inventory_key in candidates
                )
                try:
                    proposed = self._strategy.allocate(requested_by_sku, snapshots)
                    allocations = self._validate(requested_by_sku, snapshots, proposed)
                except InsufficientInventory as error:
                    return self._remember(scope, fingerprint, CommandResult(
                        CommandOutcome.REJECTED, None, str(error)
                    ))
                now = self._clock.now()
                reservation = Reservation(
                    self._ids.next_id(), canonical, allocations, now, now + ttl
                )
                with self._meta_lock:
                    if reservation.reservation_id in self._reservations:
                        raise ValueError("duplicate generated reservation ID")
                    for allocation in allocations:
                        self._balances[allocation.key].hold(allocation.quantity)
                    self._reservations[reservation.reservation_id] = reservation
                return self._remember(scope, fingerprint, CommandResult(
                    CommandOutcome.APPLIED, reservation
                ))

    def confirm(self, key: str, reservation_id: str) -> CommandResult:
        return self._terminal_command("confirm", key, reservation_id)

    def release(self, key: str, reservation_id: str) -> CommandResult:
        return self._terminal_command("release", key, reservation_id)

    def expire_due(self) -> Tuple[Reservation, ...]:
        """The guarded transition makes repeated or concurrent sweeps harmless."""
        now = self._clock.now()
        with self._meta_lock:
            due_ids = tuple(
                item.reservation_id for item in self._reservations.values()
                if item.status is ReservationStatus.ACTIVE and item.is_due(now)
            )
        expired = []
        for reservation_id in due_ids:
            reservation = self._require_reservation(reservation_id)
            with self._lock_keys(self._keys(reservation)):
                current = self._require_reservation(reservation_id)
                if current.status is ReservationStatus.ACTIVE and current.is_due(now):
                    expired.append(self._finish_active(current, ReservationStatus.EXPIRED))
        return tuple(expired)

    def get_reservation(self, reservation_id: str) -> Reservation:
        return self._require_reservation(reservation_id)

    def get_balance(self, key: InventoryKey) -> InventoryBalance:
        with self._lock_keys((key,)):
            balance = self._balances.get(key)
            return balance.snapshot(key) if balance else InventoryBalance(key, 0, 0, 0)

    def _terminal_command(
        self, operation: str, key: str, reservation_id: str
    ) -> CommandResult:
        scope, fingerprint = self._scope(operation, key), (reservation_id,)
        with self._command_lock(scope):
            replay = self._replay(scope, fingerprint)
            if replay:
                return replay
            reservation = self._require_reservation(reservation_id)
            with self._lock_keys(self._keys(reservation)):
                current = self._require_reservation(reservation_id)
                now = self._clock.now()
                if current.status is ReservationStatus.ACTIVE and current.is_due(now):
                    expired = self._finish_active(current, ReservationStatus.EXPIRED)
                    result = CommandResult(CommandOutcome.EXPIRED, expired, "TTL elapsed")
                elif current.status is ReservationStatus.ACTIVE:
                    target = (
                        ReservationStatus.CONFIRMED
                        if operation == "confirm" else ReservationStatus.RELEASED
                    )
                    changed = self._finish_active(current, target)
                    result = CommandResult(CommandOutcome.APPLIED, changed)
                elif (
                    operation == "confirm" and current.status is ReservationStatus.CONFIRMED
                ) or (
                    operation == "release" and current.status is ReservationStatus.RELEASED
                ):
                    result = CommandResult(CommandOutcome.APPLIED, current, "already applied")
                elif current.status is ReservationStatus.EXPIRED:
                    result = CommandResult(CommandOutcome.EXPIRED, current, "TTL elapsed")
                else:
                    result = CommandResult(CommandOutcome.CONFLICT, current, "terminal conflict")
                return self._remember(scope, fingerprint, result)

    def _finish_active(
        self, reservation: Reservation, target: ReservationStatus
    ) -> Reservation:
        consume = target is ReservationStatus.CONFIRMED
        for allocation in reservation.allocations:
            self._balances[allocation.key].finish(allocation.quantity, consume)
        changed = reservation.terminal(target)
        with self._meta_lock:
            self._reservations[reservation.reservation_id] = changed
        return changed

    @staticmethod
    def _validate(
        requested: Mapping[str, int],
        snapshots: Tuple[InventoryBalance, ...],
        proposed: Tuple[Allocation, ...],
    ) -> Tuple[Allocation, ...]:
        available = {item.key: item.available for item in snapshots}
        by_key: Dict[InventoryKey, int] = {}
        by_sku: Dict[str, int] = {}
        for allocation in proposed:
            if allocation.key not in available or allocation.key.sku not in requested:
                raise InvalidAllocation("strategy returned an ineligible key")
            by_key[allocation.key] = by_key.get(allocation.key, 0) + allocation.quantity
            by_sku[allocation.key.sku] = by_sku.get(allocation.key.sku, 0) + allocation.quantity
        if by_sku != dict(requested):
            raise InvalidAllocation("proposal does not exactly satisfy the request")
        if any(quantity > available[key] for key, quantity in by_key.items()):
            raise InvalidAllocation("proposal exceeds availability")
        return tuple(Allocation(key, quantity) for key, quantity in sorted(by_key.items()))

    @staticmethod
    def _canonical_request(requested: Mapping[str, int]) -> Tuple[Tuple[str, int], ...]:
        if not requested:
            raise ValueError("at least one SKU is required")
        if any(not sku.strip() or quantity <= 0 for sku, quantity in requested.items()):
            raise ValueError("SKUs must be non-blank and quantities positive")
        return tuple(sorted(requested.items()))

    @staticmethod
    def _keys(reservation: Reservation) -> Tuple[InventoryKey, ...]:
        return tuple(allocation.key for allocation in reservation.allocations)

    def _require_reservation(self, reservation_id: str) -> Reservation:
        with self._meta_lock:
            reservation = self._reservations.get(reservation_id)
        if reservation is None:
            raise InventoryError("unknown reservation {}".format(reservation_id))
        return reservation

    @staticmethod
    def _scope(operation: str, key: str) -> Tuple[str, str]:
        if not key or not key.strip():
            raise ValueError("idempotency key must not be blank")
        return operation, key

    def _replay(
        self, scope: Tuple[str, str], fingerprint: Tuple[object, ...]
    ) -> Optional[CommandResult]:
        with self._meta_lock:
            receipt = self._receipts.get(scope)
        if receipt is None:
            return None
        if receipt.fingerprint != fingerprint:
            raise IdempotencyConflict("key reused with different input")
        return receipt.result

    def _remember(
        self, scope: Tuple[str, str], fingerprint: Tuple[object, ...], result: CommandResult
    ) -> CommandResult:
        with self._meta_lock:
            self._receipts[scope] = _Receipt(fingerprint, result)
        return result

    def _command_lock(self, scope: Tuple[str, str]) -> RLock:
        with self._meta_lock:
            return self._command_locks.setdefault(scope, RLock())

    def _key_lock(self, key: InventoryKey) -> RLock:
        with self._meta_lock:
            return self._key_locks.setdefault(key, RLock())

    @contextmanager
    def _lock_keys(self, keys: Tuple[InventoryKey, ...]) -> Iterator[None]:
        locks = [self._key_lock(key) for key in sorted(set(keys))]
        for lock in locks:
            lock.acquire()
        try:
            yield
        finally:
            for lock in reversed(locks):
                lock.release()

package com.example.lld.library_management_system;

public final class Book {
    private final String isbn;
    private final String title;
    private final String author;
    private final int totalCopies;

    private int availableCopies;

    public Book(String isbn, String title, String author, int totalCopies) {
        if (isbn == null || isbn.isBlank()) {
            throw new IllegalArgumentException("ISBN is required");
        }
        if (title == null || title.isBlank()) {
            throw new IllegalArgumentException("Title is required");
        }
        if (author == null || author.isBlank()) {
            throw new IllegalArgumentException("Author is required");
        }
        if (totalCopies <= 0) {
            throw new IllegalArgumentException("A book must have at least one copy");
        }
        this.isbn = isbn;
        this.title = title;
        this.author = author;
        this.totalCopies = totalCopies;
        this.availableCopies = totalCopies;
    }

    public boolean isAvailable() {
        return availableCopies > 0;
    }

    public void lendCopy() {
        if (!isAvailable()) {
            throw new IllegalStateException("No copy is available for ISBN " + isbn);
        }
        availableCopies--;
    }

    public void returnCopy() {
        if (availableCopies == totalCopies) {
            throw new IllegalStateException("All copies are already present for ISBN " + isbn);
        }
        availableCopies++;
    }

    public String getIsbn() {
        return isbn;
    }

    public String getTitle() {
        return title;
    }

    public String getAuthor() {
        return author;
    }

    public int getTotalCopies() {
        return totalCopies;
    }

    public int getAvailableCopies() {
        return availableCopies;
    }
}

package com.example.lld.library_management_system;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.concurrent.atomic.AtomicLong;

public final class Library {
    private final Map<String, Book> books = new LinkedHashMap<>();
    private final Map<String, Member> members = new LinkedHashMap<>();
    private final Map<String, Loan> activeLoans = new LinkedHashMap<>();
    private final AtomicLong loanSequence = new AtomicLong();

    public void addBook(Book book) {
        Book requiredBook = Objects.requireNonNull(book, "book");
        if (books.putIfAbsent(requiredBook.getIsbn(), requiredBook) != null) {
            throw new IllegalArgumentException("Book already exists: " + requiredBook.getIsbn());
        }
    }

    public void addMember(Member member) {
        Member requiredMember = Objects.requireNonNull(member, "member");
        if (members.putIfAbsent(requiredMember.getId(), requiredMember) != null) {
            throw new IllegalArgumentException("Member already exists: " + requiredMember.getId());
        }
    }

    /** Returns null when the requested loan violates a lending rule. */
    public Loan lendBook(String memberId, String isbn, int loanPeriodDays) {
        if (loanPeriodDays <= 0) {
            throw new IllegalArgumentException("Loan period must be positive");
        }
        Member member = members.get(memberId);
        Book book = books.get(isbn);
        if (member == null || book == null || !book.isAvailable() || member.hasOverdueLoans()) {
            return null;
        }

        book.lendCopy();
        Loan loan = new Loan("L" + loanSequence.incrementAndGet(), book, member, loanPeriodDays);
        activeLoans.put(loan.getLoanId(), loan);
        member.addLoan(loan);
        return loan;
    }

    public boolean returnBook(String loanId) {
        Loan loan = activeLoans.remove(loanId);
        if (loan == null) {
            return false;
        }
        loan.returnBook();
        return true;
    }

    public Map<String, Book> getBooks() {
        return Map.copyOf(books);
    }

    public Map<String, Member> getMembers() {
        return Map.copyOf(members);
    }

    public Map<String, Loan> getLoans() {
        return Map.copyOf(activeLoans);
    }
}

