public interface Cache<Key, Value> {
    void put(Key k, Value v);
    Value get(Key k);
    void delete(Key k);

    int size();
}

package code;

import code.policies.EvictionPolicy;
import code.storage.Storage;

public class CacheImpl<Key, Value> implements Cache<Key, Value> {

    Storage<Key, Value> storage;
    EvictionPolicy<Key> evictionPolicy;

    CacheImpl(Storage<Key, Value> storage, EvictionPolicy<Key> evictionPolicy){
        this.storage = storage;
        this.evictionPolicy = evictionPolicy;
    }

    @Override
    public void put(Key k, Value v) {
        if(!storage.isPresent(k) && storage.isFull()){
           Key evictedKey = evictionPolicy.keyToEvict();
           storage.delete(evictedKey);
           evictionPolicy.delete(evictedKey);
        }
        storage.add(k, v);
        evictionPolicy.accessedKey(k);
    }

    @Override
    public Value get(Key k) {
        if(storage.isPresent(k)){
            evictionPolicy.accessedKey(k);
            return storage.fetch(k);
        }
        return null;
    }

    @Override
    public void delete(Key k) {
       if(storage.isPresent(k)){
           evictionPolicy.delete(k);
           storage.delete(k);
       }
    }

    @Override
    public int size() {
        return storage.getSize();
    }
}

package code;

import code.models.LevelCacheData;
import code.models.ReadResponse;
import code.models.UsageResponse;
import code.models.WriteResponse;

import java.util.List;

public class DefaultLevelCache<Key, Value> implements ILevelCache<Key, Value>{
    LevelCacheData levelCacheData;

    public DefaultLevelCache(int readTime, int writeTime, int capacity, Cache<Key, Value> cache, ILevelCache<Key, Value> next){
        this.levelCacheData = new LevelCacheData(readTime, writeTime, capacity);
        this.cache = cache;
        this.next = next;
    }

    Cache<Key, Value> cache;
    ILevelCache<Key, Value> next;

    @Override
    public ReadResponse<Value> read(Key key){
        double timeTaken = levelCacheData.readTime();
        Value val = cache.get(key);

        if(val == null){
            ReadResponse<Value> nextResponse = next.read(key);
            val = nextResponse.value();
            timeTaken += nextResponse.timeTaken();

            if(val != null){
               cache.put(key, val);
               timeTaken += levelCacheData.writeTime();
            }
        }
        return new ReadResponse<>(val, timeTaken);
    }

    @Override
    public WriteResponse write(Key key, Value value){

        double timeTaken = levelCacheData.readTime();
        Value val = cache.get(key);

        if(val == null || val != value){
            timeTaken += levelCacheData.writeTime();
            cache.put(key, value);

            WriteResponse nextResponse = next.write(key, value);
            timeTaken += nextResponse.time();
        }

        return new WriteResponse(timeTaken);
    }

    @Override
    public List<UsageResponse> usageStats(){
        List<UsageResponse> usageResponses = next.usageStats();
        UsageResponse currentUsage = new UsageResponse(cache.size(), levelCacheData.capacity());
        usageResponses.add(currentUsage);
        return usageResponses;
    }
}

