package com.example.lld.parking_lot;

public final class Main {
    private Main() {
    }

    public static void main(String[] args) {
        ParkingLotService service = new ParkingLotService();
        OutputPrinter printer = new OutputPrinter();

        service.createParkingLot(3, new NaturalNumberStrategy());
        printer.parkingLotCreated(3);

        int firstSlot = service.parkVehicle(new Vehicle("KA-01-HH-1234", "White"));
        printer.allocated(firstSlot);
        printer.allocated(service.parkVehicle(new Vehicle("KA-01-HH-9999", "Black")));
        printer.status(service.status());

        System.out.println("White registrations: " + service.carNumbersWithColor("white"));
        service.unparkVehicle(firstSlot);
        printer.freed(firstSlot);
    }
}

package com.example.lld.parking_lot;

import java.util.NoSuchElementException;
import java.util.TreeSet;

/** Allocates the lowest numbered available spot. */
public final class NaturalNumberStrategy implements ParkingStrategy {
    private final TreeSet<Integer> availableIds = new TreeSet<>();

    @Override
    public void reset() {
        availableIds.clear();
    }

    @Override
    public void addId(int id) {
        if (id <= 0) {
            throw new IllegalArgumentException("Parking spot number must be positive");
        }
        availableIds.add(id);
    }

    @Override
    public int getNextSlot() {
        if (availableIds.isEmpty()) {
            throw new NoSuchElementException("Parking lot is full");
        }
        return availableIds.first();
    }

    @Override
    public void removeId(int id) {
        if (!availableIds.remove(id)) {
            throw new IllegalStateException("Parking spot is not available: " + id);
        }
    }
}

