}

package com.example.lld.parking_lot;

import java.util.LinkedHashMap;
import java.util.Map;

public final class ParkingLot {
    private final int capacity;
    private final Map<Integer, ParkingSpot> spots = new LinkedHashMap<>();

    public ParkingLot(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Parking lot capacity must be positive");
        }
        this.capacity = capacity;
        for (int slot = 1; slot <= capacity; slot++) {
            spots.put(slot, new ParkingSpot(slot));
        }
    }

    public void park(int slotId, Vehicle vehicle) {
        requireSpot(slotId).assignCar(vehicle);
    }

    public Vehicle unpark(int slotId) {
        return requireSpot(slotId).makeFree();
    }

    public int getCapacity() {
        return capacity;
    }

    public Map<Integer, ParkingSpot> getSpots() {
        return Map.copyOf(spots);
    }

    private ParkingSpot requireSpot(int slotId) {
        ParkingSpot spot = spots.get(slotId);
        if (spot == null) {
            throw new IllegalArgumentException("Unknown parking spot: " + slotId);
        }
        return spot;
    }
}

package com.example.lld.parking_lot;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;

public final class ParkingLotService {
    private final Map<String, Integer> slotByVehicleNo = new LinkedHashMap<>();
    private final Map<String, Set<String>> vehicleNumbersByColor = new LinkedHashMap<>();

    private ParkingLot parkingLot;
    private ParkingStrategy parkingStrategy;

    public void createParkingLot(int capacity, ParkingStrategy strategy) {
        parkingLot = new ParkingLot(capacity);
        parkingStrategy = Objects.requireNonNull(strategy, "strategy");
        parkingStrategy.reset();
        slotByVehicleNo.clear();
        vehicleNumbersByColor.clear();

        for (int slot = 1; slot <= capacity; slot++) {
            parkingStrategy.addId(slot);
        }
    }

    public int parkVehicle(Vehicle vehicle) {
        ensureCreated();
        Vehicle requiredVehicle = Objects.requireNonNull(vehicle, "vehicle");
        if (slotByVehicleNo.containsKey(requiredVehicle.no())) {
            throw new IllegalArgumentException("Vehicle is already parked: " + requiredVehicle.no());
        }

        int slotId = parkingStrategy.getNextSlot();
        parkingLot.park(slotId, requiredVehicle);
        parkingStrategy.removeId(slotId);
        slotByVehicleNo.put(requiredVehicle.no(), slotId);
        vehicleNumbersByColor
                .computeIfAbsent(normalizeColor(requiredVehicle.color()), ignored -> new LinkedHashSet<>())
                .add(requiredVehicle.no());
        return slotId;
    }

    public Vehicle unparkVehicle(String vehicleNo) {
        ensureCreated();
        Integer slotId = slotByVehicleNo.get(vehicleNo);
        if (slotId == null) {
            throw new IllegalArgumentException("Vehicle is not parked: " + vehicleNo);
        }
        return unparkVehicle(slotId);
    }

    public Vehicle unparkVehicle(int slotId) {
        ensureCreated();
        Vehicle vehicle = parkingLot.unpark(slotId);
        parkingStrategy.addId(slotId);
        slotByVehicleNo.remove(vehicle.no());

        String colorKey = normalizeColor(vehicle.color());
        Set<String> registrations = vehicleNumbersByColor.get(colorKey);
        if (registrations != null) {
            registrations.remove(vehicle.no());
            if (registrations.isEmpty()) {
                vehicleNumbersByColor.remove(colorKey);
            }
        }
        return vehicle;
    }

    public List<ParkingSpot> status() {
        ensureCreated();
        return parkingLot.getSpots().values().stream()
                .filter(ParkingSpot::isOccupied)
                .sorted(Comparator.comparingInt(ParkingSpot::getNo))
                .toList();
    }

    public int getSlotNoByVehicleNo(Vehicle vehicle) {
        return getSlotNoByVehicleNo(vehicle.no());
    }

    public int getSlotNoByVehicleNo(String vehicleNo) {
        ensureCreated();
        return slotByVehicleNo.getOrDefault(vehicleNo, -1);
    }

    public List<Integer> slotsNoOfCarWithColor(String color) {
        List<Integer> slots = new ArrayList<>();
        for (String vehicleNo : registrationsForColor(color)) {
            slots.add(slotByVehicleNo.get(vehicleNo));
        }
        slots.sort(Integer::compareTo);
        return List.copyOf(slots);
    }

    public List<String> carNumbersWithColor(String color) {
        return List.copyOf(registrationsForColor(color));
    }

    public ParkingLot getParkingLot() {
        ensureCreated();
        return parkingLot;
    }

    private Set<String> registrationsForColor(String color) {
        ensureCreated();
        return vehicleNumbersByColor.getOrDefault(normalizeColor(color), Set.of());
    }

    private String normalizeColor(String color) {
        if (color == null || color.isBlank()) {
            throw new IllegalArgumentException("Color is required");
        }
        return color.trim().toLowerCase(Locale.ROOT);
    }

    private void ensureCreated() {
        if (parkingLot == null || parkingStrategy == null) {
            throw new IllegalStateException("Create the parking lot before using it");
        }
    }
}

package com.example.lld.parking_lot;

import java.util.Optional;

public final class ParkingSpot {
    private final int no;
    private Vehicle vehicle;

    public ParkingSpot(int no) {
        if (no <= 0) {
            throw new IllegalArgumentException("Parking spot number must be positive");
        }
        this.no = no;
    }

    public void assignCar(Vehicle vehicle) {
        if (isOccupied()) {
            throw new IllegalStateException("Parking spot " + no + " is already occupied");
        }
        if (vehicle == null) {
            throw new IllegalArgumentException("Vehicle is required");
        }
        this.vehicle = vehicle;
    }

    public Vehicle makeFree() {
        if (!isOccupied()) {
            throw new IllegalStateException("Parking spot " + no + " is already free");
        }
        Vehicle parkedVehicle = vehicle;
        vehicle = null;
        return parkedVehicle;
    }

    public boolean isOccupied() {
        return vehicle != null;
    }

    public int getNo() {
        return no;
    }

    public Vehicle getVehicle() {
        return vehicle;
    }

    public Optional<Vehicle> vehicle() {
        return Optional.ofNullable(vehicle);
    }
}

package com.example.lld.parking_lot;

public interface ParkingStrategy {
    void reset();

    void addId(int id);

    int getNextSlot();

    void removeId(int id);
}

package com.example.lld.parking_lot;

public record Vehicle(String no, String color) {
    public Vehicle {
        if (no == null || no.isBlank()) {
            throw new IllegalArgumentException("Vehicle registration number is required");
        }
        if (color == null || color.isBlank()) {
            throw new IllegalArgumentException("Vehicle color is required");
        }
    }
}

"""One-hour payment-processing core: exact money, retries, and reconciliation."""

from __future__ import annotations

from dataclasses import dataclass, replace
from decimal import Decimal
from enum import Enum
from threading import Event, RLock
from typing import Any, Callable, Dict, List, Optional, Protocol, Tuple
class PaymentError(Exception): pass
class InvalidState(PaymentError): pass
class AmountExceeded(PaymentError): pass
class OperationInProgress(PaymentError): pass
class IdempotencyConflict(PaymentError): pass
class CallbackError(PaymentError): pass
def _text(value: str, name: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ValueError("{} must not be blank".format(name))
    return value.strip()
@dataclass(frozen=True)
class Money:
    amount: Decimal
    currency: str

    def __post_init__(self) -> None:
        if not isinstance(self.amount, Decimal):
            raise TypeError("amount must be Decimal")
        if not self.amount.is_finite():
            raise ValueError("amount must be finite")
        currency = _text(self.currency, "currency").upper()
        if len(currency) != 3 or not currency.isalpha():
            raise ValueError("currency must be a three-letter code")
        object.__setattr__(self, "currency", currency)

    @classmethod
    def of(cls, amount: str, currency: str = "USD") -> "Money":
        return cls(Decimal(amount), currency)

    @classmethod
    def zero(cls, currency: str) -> "Money":
        return cls(Decimal("0"), currency)

    def positive(self) -> None:
        if self.amount <= 0:
            raise ValueError("money must be positive")

    def add(self, other: "Money") -> "Money":
        if self.currency != other.currency:
            raise ValueError("currency mismatch")
        return Money(self.amount + other.amount, self.currency)
class Operation(str, Enum):
    AUTHORIZE = "authorize"
    CAPTURE = "capture"
    VOID = "void"
    REFUND = "refund"

class ProviderOutcome(str, Enum):
    APPROVED = "approved"
    DECLINED = "declined"
    FAILED = "failed"  # Provider proves no money moved; a new command may retry.
    UNKNOWN = "unknown"  # Timeout/ambiguous transport; do not issue new work.

class AttemptStatus(str, Enum):
    PENDING = "pending"
    SUCCEEDED = "succeeded"
    DECLINED = "declined"
    FAILED = "failed"
    UNKNOWN = "unknown"

class PaymentStatus(str, Enum):
    CREATED = "created"
    AUTHORIZING = "authorizing"
    AUTHORIZED = "authorized"
    PARTIALLY_CAPTURED = "partially_captured"
    CAPTURED = "captured"
    VOIDED = "voided"
    DECLINED = "declined"
    FAILED = "failed"
    PARTIALLY_REFUNDED = "partially_refunded"
    REFUNDED = "refunded"

class CallbackDisposition(str, Enum):
    APPLIED = "applied"
    DUPLICATE = "duplicate"
    STALE = "stale"

@dataclass(frozen=True)
class ProviderResponse:
    outcome: ProviderOutcome
    reference: Optional[str] = None
    detail: str = ""

    def __post_init__(self) -> None:
        if self.reference is not None:
            object.__setattr__(self, "reference", _text(self.reference, "reference"))
        if self.outcome is ProviderOutcome.APPROVED and self.reference is None:
            raise ValueError("approved response requires a provider reference")

    @classmethod
    def approved(cls, reference: str) -> "ProviderResponse":
        return cls(ProviderOutcome.APPROVED, reference)

    @classmethod
    def unknown(cls, detail: str = "outcome unknown") -> "ProviderResponse":
        return cls(ProviderOutcome.UNKNOWN, detail=detail)

@dataclass(frozen=True)
class ProviderRequest:
    request_id: str
    payment_id: str
    order_id: str
    operation: Operation
    amount: Money
    method_token: str

@dataclass(frozen=True)
class ProviderCallback:
    callback_id: str
    provider_name: str
    request_id: str
    payment_id: str
    operation: Operation
    amount: Money
    response: ProviderResponse

class PaymentProvider(Protocol):
    name: str

    def execute(self, request: ProviderRequest) -> ProviderResponse: ...

@dataclass(frozen=True)
class Attempt:
    attempt_id: str
    request_id: str
    operation: Operation
    amount: Money
    status: AttemptStatus
    reference: Optional[str] = None
    detail: str = ""

@dataclass(frozen=True)
class PaymentSnapshot:
    payment_id: str
    order_id: str
    intent: Money
    captured: Money
    refunded: Money
    status: PaymentStatus
    pending_request_id: Optional[str]
    attempts: Tuple[Attempt, ...]

@dataclass(frozen=True)
class CommandResult:
    payment: PaymentSnapshot
    attempt: Optional[Attempt]

class _Payment:
    """The aggregate lock is a stand-in for a versioned database row."""

    def __init__(
        self,
        payment_id: str,
        order_id: str,
        intent: Money,
        method_token: str,
        provider_name: str,
    ) -> None:
        intent.positive()
        self.payment_id = _text(payment_id, "payment_id")
        self.order_id = _text(order_id, "order_id")
        self.intent = intent
        self.method_token = _text(method_token, "method_token")
        self.provider_name = _text(provider_name, "provider_name")
        self.captured = Money.zero(intent.currency)
        self.refunded = Money.zero(intent.currency)
        self.authorized = False
        self.voided = False
        self.status = PaymentStatus.CREATED
        self.pending: Optional[str] = None
        self.attempts: Dict[str, Attempt] = {}
        self.callbacks: Dict[str, Tuple[Any, ...]] = {}
        self.lock = RLock()

    def begin(self, attempt_id: str, request_id: str, op: Operation, amount: Money) -> None:
        with self.lock:
            if self.pending is not None:
                raise OperationInProgress("unresolved provider request {}".format(self.pending))
            self._validate(op, amount)
            self.attempts[request_id] = Attempt(
                attempt_id, request_id, op, amount, AttemptStatus.PENDING
            )
            self.pending = request_id
            if op is Operation.AUTHORIZE:
                self.status = PaymentStatus.AUTHORIZING

    def settle(self, request_id: str, response: ProviderResponse) -> Attempt:
        with self.lock:
            current = self.attempts.get(request_id)
            if current is None:
                raise CallbackError("unknown provider request")
            if current.status not in (AttemptStatus.PENDING, AttemptStatus.UNKNOWN):
                return current
            if response.outcome is ProviderOutcome.UNKNOWN:
                result = replace(
                    current,
                    status=AttemptStatus.UNKNOWN,
                    reference=response.reference,
                    detail=response.detail,
                )
                self.attempts[request_id] = result
                return result
            attempt_status = {
                ProviderOutcome.APPROVED: AttemptStatus.SUCCEEDED,
                ProviderOutcome.DECLINED: AttemptStatus.DECLINED,
                ProviderOutcome.FAILED: AttemptStatus.FAILED,
            }[response.outcome]
            result = replace(
                current,
                status=attempt_status,
                reference=response.reference,
                detail=response.detail,
            )
            self.attempts[request_id] = result
            self.pending = None
            if response.outcome is ProviderOutcome.APPROVED:
                self._apply(current.operation, current.amount)
            elif current.operation is Operation.AUTHORIZE:
                self.status = (
                    PaymentStatus.DECLINED
                    if response.outcome is ProviderOutcome.DECLINED
                    else PaymentStatus.FAILED
                )
            else:
                self.status = self._derived_status()
            return result

    def reconcile(self, callback: ProviderCallback) -> CallbackDisposition:
        with self.lock:
            callback_id = _text(callback.callback_id, "callback_id")
            attempt = self.attempts.get(callback.request_id)
            if callback.payment_id != self.payment_id or callback.provider_name != self.provider_name:
                raise CallbackError("callback route does not match payment")
            if attempt is None or attempt.operation is not callback.operation or attempt.amount != callback.amount:
                raise CallbackError("callback does not match attempt")
            fingerprint = (
                callback.provider_name,
                callback.request_id,
                callback.payment_id,
                callback.operation,
                callback.amount,
                callback.response,
            )
            prior = self.callbacks.get(callback_id)
            if prior is not None:
                if prior != fingerprint:
                    raise IdempotencyConflict("callback ID reused with different content")
                return CallbackDisposition.DUPLICATE
            self.callbacks[callback_id] = fingerprint
            if attempt.status not in (AttemptStatus.PENDING, AttemptStatus.UNKNOWN):
                return CallbackDisposition.STALE
            self.settle(callback.request_id, callback.response)
            return CallbackDisposition.APPLIED

    def snapshot(self) -> PaymentSnapshot:
        with self.lock:
            return PaymentSnapshot(
                self.payment_id,
                self.order_id,
                self.intent,
                self.captured,
                self.refunded,
                self.status,
                self.pending,
                tuple(self.attempts.values()),
            )

    def _validate(self, op: Operation, amount: Money) -> None:
        amount.positive()
        self.intent.add(Money.zero(amount.currency))  # Validates currency.
        if op is Operation.AUTHORIZE:
            if self.status not in (PaymentStatus.CREATED, PaymentStatus.FAILED):
                raise InvalidState("authorization is not allowed")
            if amount != self.intent:
                raise ValueError("authorization must equal intent")
        elif op is Operation.CAPTURE:
            if not self.authorized or self.voided:
                raise InvalidState("capture requires active authorization")
            if self.captured.add(amount).amount > self.intent.amount:
                raise AmountExceeded("capture exceeds authorization")
        elif op is Operation.VOID:
            if not self.authorized or self.voided or self.captured.amount:
                raise InvalidState("only an uncaptured authorization can be voided")
            if amount != self.intent:
                raise ValueError("void must target full authorization")
        elif op is Operation.REFUND:
            if not self.captured.amount:
                raise InvalidState("refund requires captured funds")
            if self.refunded.add(amount).amount > self.captured.amount:
                raise AmountExceeded("refund exceeds captured amount")

    def _apply(self, op: Operation, amount: Money) -> None:
        if op is Operation.AUTHORIZE:
            self.authorized = True
            self.status = PaymentStatus.AUTHORIZED
        elif op is Operation.CAPTURE:
            self.captured = self.captured.add(amount)
            self.status = self._derived_status()
        elif op is Operation.VOID:
            self.voided = True
            self.status = PaymentStatus.VOIDED
        else:
            self.refunded = self.refunded.add(amount)
            self.status = self._derived_status()

    def _derived_status(self) -> PaymentStatus:
        if self.voided:
            return PaymentStatus.VOIDED
        if self.refunded.amount:
            return (
                PaymentStatus.REFUNDED
                if self.refunded == self.captured
                else PaymentStatus.PARTIALLY_REFUNDED
            )
        if self.captured.amount:
            return (
                PaymentStatus.CAPTURED
                if self.captured == self.intent
                else PaymentStatus.PARTIALLY_CAPTURED
            )
        return PaymentStatus.AUTHORIZED if self.authorized else PaymentStatus.CREATED
@dataclass
class _IdempotencyEntry:
    fingerprint: Tuple[Any, ...]
    done: Event
    result: Any = None
    error: Optional[BaseException] = None
class PaymentService:
    def __init__(self, providers: List[PaymentProvider]) -> None:
        self.providers = {_text(provider.name, "provider name"): provider for provider in providers}
        if len(self.providers) != len(providers) or not providers:
            raise ValueError("provider names must be non-empty and unique")
        self.payments: Dict[str, _Payment] = {}
        self.routes: Dict[str, str] = {}
        self.idempotency: Dict[str, _IdempotencyEntry] = {}
        self.sequence = 0
        self.lock = RLock()

    def create(
        self,
        payment_id: str,
        order_id: str,
        amount: Money,
        method_token: str,
        provider_name: str,
        key: str,
    ) -> CommandResult:
        payment_id, order_id = _text(payment_id, "payment_id"), _text(order_id, "order_id")
        method_token, provider_name = _text(method_token, "method_token"), _text(provider_name, "provider_name")
        fingerprint = ("create", payment_id, order_id, amount, method_token, provider_name)

        def action() -> CommandResult:
            if provider_name not in self.providers:
                raise ValueError("unknown provider")
            payment = _Payment(payment_id, order_id, amount, method_token, provider_name)
            with self.lock:
                if payment_id in self.payments:
                    raise PaymentError("duplicate payment")
                self.payments[payment_id] = payment
            return CommandResult(payment.snapshot(), None)

        return self._once(key, fingerprint, action)

    def authorize(self, payment_id: str, key: str) -> CommandResult:
        payment = self._payment(payment_id)
        return self._command(payment, Operation.AUTHORIZE, payment.intent, key)

    def capture(self, payment_id: str, amount: Money, key: str) -> CommandResult:
        return self._command(self._payment(payment_id), Operation.CAPTURE, amount, key)

    def void(self, payment_id: str, key: str) -> CommandResult:
        payment = self._payment(payment_id)
        return self._command(payment, Operation.VOID, payment.intent, key)

    def refund(self, payment_id: str, amount: Money, key: str) -> CommandResult:
        return self._command(self._payment(payment_id), Operation.REFUND, amount, key)

    def callback(self, callback: ProviderCallback) -> Tuple[CallbackDisposition, PaymentSnapshot]:
        with self.lock:
            payment_id = self.routes.get(callback.request_id)
        if payment_id != callback.payment_id:
            raise CallbackError("callback has no matching route")
        payment = self._payment(payment_id)
        return payment.reconcile(callback), payment.snapshot()

    def get(self, payment_id: str) -> PaymentSnapshot:
        return self._payment(payment_id).snapshot()

    def _command(self, payment: _Payment, op: Operation, amount: Money, key: str) -> CommandResult:
        def action() -> CommandResult:
            with self.lock:
                self.sequence += 1
                attempt_id = "attempt-{}".format(self.sequence)
                request_id = "request-{}".format(self.sequence)
            payment.begin(attempt_id, request_id, op, amount)
            with self.lock:
                self.routes[request_id] = payment.payment_id
            request = ProviderRequest(
                request_id, payment.payment_id, payment.order_id, op, amount, payment.method_token
            )
            try:
                response = self.providers[payment.provider_name].execute(request)
            except Exception as error:  # No proof that the provider did not execute.
                response = ProviderResponse.unknown(type(error).__name__)
            attempt = payment.settle(request_id, response)
            return CommandResult(payment.snapshot(), attempt)

        return self._once(key, (op.value, payment.payment_id, amount), action)

    def _payment(self, payment_id: str) -> _Payment:
        with self.lock:
            payment = self.payments.get(_text(payment_id, "payment_id"))
        if payment is None:
            raise KeyError("unknown payment")
        return payment

    def _once(
        self, key: str, fingerprint: Tuple[Any, ...], action: Callable[[], Any]
    ) -> Any:
        key = _text(key, "idempotency key")
        with self.lock:
            entry = self.idempotency.get(key)
            owner = entry is None
            if owner:
                entry = _IdempotencyEntry(fingerprint, Event())
                self.idempotency[key] = entry
            elif entry.fingerprint != fingerprint:
                raise IdempotencyConflict("key reused for another command")
        assert entry is not None
        if owner:
            try:
                entry.result = action()
            except BaseException as error:
                entry.error = error
            finally:
                entry.done.set()
        else:
            entry.done.wait()
        if entry.error is not None:
            raise entry.error
        return entry.result

package com.example.lld.payment_processing_service;

import com.example.lld.payment_processing_service.domain.CallbackDisposition;
import com.example.lld.payment_processing_service.domain.CallbackResult;
import com.example.lld.payment_processing_service.domain.CommandResult;
import com.example.lld.payment_processing_service.domain.Money;
import com.example.lld.payment_processing_service.domain.PaymentMethodToken;
import com.example.lld.payment_processing_service.domain.PaymentOperation;
import com.example.lld.payment_processing_service.domain.PaymentSnapshot;
import com.example.lld.payment_processing_service.domain.PaymentStatus;
import com.example.lld.payment_processing_service.exception.AmountLimitExceededException;
import com.example.lld.payment_processing_service.provider.FakePaymentProvider;
import com.example.lld.payment_processing_service.provider.ProviderCallback;
import com.example.lld.payment_processing_service.provider.ProviderOutcome;
import com.example.lld.payment_processing_service.service.PaymentService;
import java.time.Clock;
import java.util.List;

/** Runnable assertions for the important success, failure, retry, and callback paths. */
public final class Demo {
    private static final PaymentMethodToken TOKEN = new PaymentMethodToken("tok_demo_opaque");

    private Demo() {}

    public static void main(String[] args) {
        FakePaymentProvider provider = new FakePaymentProvider("deterministic-pay");
        PaymentService service = new PaymentService(Clock.systemUTC(), List.of(provider));

        successfulPartialCaptureAndIdempotentRetry(service, provider);
        declinedAuthorization(service, provider);
        timeoutLateCallbackAndStaleCallback(service, provider);
        partialRefundAndDuplicateCallback(service, provider);
        voidAuthorization(service);

        System.out.println("All payment processing scenarios passed.");
    }

    private static void successfulPartialCaptureAndIdempotentRetry(
            PaymentService service, FakePaymentProvider provider) {
        create(service, "pay-success", "order-100", "100.00", "create-success");
        CommandResult authorized = service.authorize("pay-success", "authorize-success");
        check(authorized.payment().status() == PaymentStatus.AUTHORIZED, "authorization failed");

        service.capture("pay-success", usd("40.00"), "capture-first");
        int callsBefore = provider.callCount();
        CommandResult second = service.capture("pay-success", usd("60.00"), "capture-second");
        CommandResult replay = service.capture("pay-success", usd("60.00"), "capture-second");
        check(second == replay, "idempotent replay did not return the original result");
        check(provider.callCount() == callsBefore + 1, "capture replay called provider twice");
        check(second.payment().capturedTotal().equals(usd("100.00")), "capture total is wrong");
        check(second.payment().status() == PaymentStatus.CAPTURED, "payment is not captured");

        boolean excessiveRejected = false;
        try {
            service.capture("pay-success", usd("0.01"), "capture-excessive");
        } catch (AmountLimitExceededException expected) {
            excessiveRejected = true;
        }
        check(excessiveRejected, "excessive capture was accepted");
        System.out.println("success + two partial captures + idempotent retry: CAPTURED");
    }

    private static void declinedAuthorization(
            PaymentService service, FakePaymentProvider provider) {
        provider.enqueue(PaymentOperation.AUTHORIZE, ProviderOutcome.DECLINED, "do not honor");
        create(service, "pay-decline", "order-200", "25.00", "create-decline");
        PaymentSnapshot declined = service.authorize("pay-decline", "authorize-decline").payment();
        check(declined.status() == PaymentStatus.DECLINED, "decline was not terminal");
        check(declined.pendingProviderRequestId().isEmpty(), "decline left pending work");
        System.out.println("provider decline: DECLINED");
    }

    private static void timeoutLateCallbackAndStaleCallback(
            PaymentService service, FakePaymentProvider provider) {
        provider.enqueue(PaymentOperation.AUTHORIZE, ProviderOutcome.UNKNOWN, "network timeout");
        create(service, "pay-timeout", "order-300", "30.00", "create-timeout");
        CommandResult timedOut = service.authorize("pay-timeout", "authorize-timeout");
        check(timedOut.payment().status() == PaymentStatus.AUTHORIZING, "timeout regressed state");
        String requestId = timedOut.providerAttempt().orElseThrow().providerRequestId();

        ProviderCallback lateSuccess = provider.terminalCallback(
                requestId, "callback-auth-success", ProviderOutcome.APPROVED, "authorized later");
        CallbackResult applied = service.handleCallback(lateSuccess);
        check(applied.disposition() == CallbackDisposition.APPLIED, "late callback was not applied");
        check(applied.payment().status() == PaymentStatus.AUTHORIZED, "late auth did not succeed");

        ProviderCallback outOfOrder = provider.terminalCallback(
                requestId, "callback-auth-old", ProviderOutcome.DECLINED, "older decline arrived last");
        CallbackResult stale = service.handleCallback(outOfOrder);
        check(stale.disposition() == CallbackDisposition.STALE, "out-of-order callback not ignored");
        check(stale.payment().status() == PaymentStatus.AUTHORIZED, "stale callback regressed state");
        System.out.println("timeout + late callback + out-of-order callback: AUTHORIZED");
    }

    private static void partialRefundAndDuplicateCallback(
            PaymentService service, FakePaymentProvider provider) {
        provider.enqueue(PaymentOperation.REFUND, ProviderOutcome.UNKNOWN, "refund timed out");
        CommandResult timedOut = service.refund("pay-success", usd("25.00"), "refund-partial");
        String requestId = timedOut.providerAttempt().orElseThrow().providerRequestId();
        ProviderCallback callback = provider.terminalCallback(
                requestId, "callback-refund-25", ProviderOutcome.APPROVED, "refund completed");
        CallbackResult first = service.handleCallback(callback);
        CallbackResult duplicate = service.handleCallback(callback);
        check(first.disposition() == CallbackDisposition.APPLIED, "refund callback not applied");
        check(duplicate.disposition() == CallbackDisposition.DUPLICATE, "duplicate not ignored");
        check(first.payment().refundedTotal().equals(usd("25.00")), "refund total is wrong");
        check(first.payment().status() == PaymentStatus.PARTIALLY_REFUNDED, "refund state is wrong");
        check(duplicate.payment().refundedTotal().equals(usd("25.00")), "refund happened twice");
        System.out.println("partial refund + duplicate callback: PARTIALLY_REFUNDED once");
    }

    private static void voidAuthorization(PaymentService service) {
        create(service, "pay-void", "order-400", "15.00", "create-void");
        service.authorize("pay-void", "authorize-void");
        PaymentSnapshot voided = service.voidAuthorization("pay-void", "void-command").payment();
        check(voided.status() == PaymentStatus.VOIDED, "authorization was not voided");
        System.out.println("uncaptured authorization: VOIDED");
    }

    private static void create(
            PaymentService service,
            String paymentId,
            String orderId,
            String amount,
            String idempotencyKey) {
        CommandResult created = service.createPayment(
                paymentId, orderId, usd(amount), TOKEN, "deterministic-pay", idempotencyKey);
        check(created.payment().status() == PaymentStatus.CREATED, "payment was not created");
    }

    private static Money usd(String amount) {
        return Money.of(amount, "USD");
    }

    private static void check(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

