package com.example.lld.product_catalog_service.service;

import com.example.lld.product_catalog_service.exception.CategoryAlreadyExistsException;
import com.example.lld.product_catalog_service.exception.CategoryNotFoundException;
import com.example.lld.product_catalog_service.exception.VersionConflictException;
import com.example.lld.product_catalog_service.model.Category;
import com.example.lld.product_catalog_service.model.CategoryId;
import com.example.lld.product_catalog_service.port.CategoryRepository;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public final class InMemoryCategoryRepository implements CategoryRepository {
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock(true);
    private final Map<CategoryId, Category> categories = new HashMap<>();

    @Override
    public Category insert(Category category) {
        lock.writeLock().lock();
        try {
            if (categories.containsKey(category.id())) {
                throw new CategoryAlreadyExistsException(category.id());
            }
            categories.put(category.id(), category);
            return category;
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public Category replace(Category category, long expectedSchemaVersion) {
        lock.writeLock().lock();
        try {
            Category current = categories.get(category.id());
            if (current == null) {
                throw new CategoryNotFoundException(category.id());
            }
            if (current.schemaVersion() != expectedSchemaVersion) {
                throw new VersionConflictException(
                        "category schema",
                        category.id().value(),
                        expectedSchemaVersion,
                        current.schemaVersion());
            }
            if (category.schemaVersion() != expectedSchemaVersion + 1) {
                throw new IllegalArgumentException("replacement category must increment schemaVersion by one");
            }
            if (!category.parentId().equals(current.parentId())) {
                throw new IllegalArgumentException("schema replacement cannot change the category parent");
            }
            categories.put(category.id(), category);
            return category;
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public Optional<Category> findById(CategoryId categoryId) {
        lock.readLock().lock();
        try {
            return Optional.ofNullable(categories.get(categoryId));
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public List<Category> findAll() {
        lock.readLock().lock();
        try {
            return List.copyOf(new ArrayList<>(categories.values()));
        } finally {
            lock.readLock().unlock();
        }
    }
}

package com.example.lld.product_catalog_service.service;

import com.example.lld.product_catalog_service.exception.DuplicateSkuException;
import com.example.lld.product_catalog_service.exception.InvalidProductUpdateException;
import com.example.lld.product_catalog_service.exception.ProductAlreadyExistsException;
import com.example.lld.product_catalog_service.exception.ProductNotFoundException;
import com.example.lld.product_catalog_service.exception.VersionConflictException;
import com.example.lld.product_catalog_service.model.Product;
import com.example.lld.product_catalog_service.model.ProductId;
import com.example.lld.product_catalog_service.model.ProductVersion;
import com.example.lld.product_catalog_service.model.Sku;
import com.example.lld.product_catalog_service.model.Variant;
import com.example.lld.product_catalog_service.model.VariantId;
import com.example.lld.product_catalog_service.port.ProductRepository;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.locks.ReentrantReadWriteLock;
import java.util.function.Function;
import java.util.stream.Collectors;

public final class InMemoryProductRepository implements ProductRepository {
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock(true);
    private final Map<ProductId, Product> products = new HashMap<>();
    private final Map<Sku, ProductId> permanentSkuOwners = new HashMap<>();
    private final Map<ProductId, List<ProductVersion>> histories = new HashMap<>();

    @Override
    public Product insert(Product product, ProductVersion initialVersion) {
        lock.writeLock().lock();
        try {
            if (products.containsKey(product.id())) {
                throw new ProductAlreadyExistsException(product.id());
            }
            verifyHistoryEntry(product, initialVersion);
            ensureSkusAvailable(product);
            reserveSkus(product);
            products.put(product.id(), product);
            histories.put(product.id(), new ArrayList<>(List.of(initialVersion)));
            return product;
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public Product replace(Product product, long expectedVersion, ProductVersion newVersion) {
        lock.writeLock().lock();
        try {
            Product current = products.get(product.id());
            if (current == null) {
                throw new ProductNotFoundException(product.id());
            }
            if (current.version() != expectedVersion) {
                throw new VersionConflictException(
                        "product",
                        product.id().value(),
                        expectedVersion,
                        current.version());
            }
            if (product.version() != expectedVersion + 1) {
                throw new IllegalArgumentException("replacement product must increment version by one");
            }
            if (!product.createdAt().equals(current.createdAt())) {
                throw new InvalidProductUpdateException(product.id(), "createdAt is immutable");
            }
            verifyStableVariants(current, product);
            verifyHistoryEntry(product, newVersion);
            ensureSkusAvailable(product);
            reserveSkus(product);
            products.put(product.id(), product);
            histories.get(product.id()).add(newVersion);
            return product;
        } finally {
            lock.writeLock().unlock();
        }
    }

    @Override
    public Optional<Product> findById(ProductId productId) {
        lock.readLock().lock();
        try {
            return Optional.ofNullable(products.get(productId));
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public Optional<Product> findBySku(Sku sku) {
        lock.readLock().lock();
        try {
            ProductId owner = permanentSkuOwners.get(sku);
            return owner == null ? Optional.empty() : Optional.ofNullable(products.get(owner));
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public List<Product> findAll() {
        lock.readLock().lock();
        try {
            return List.copyOf(new ArrayList<>(products.values()));
        } finally {
            lock.readLock().unlock();
        }
    }

    @Override
    public List<ProductVersion> history(ProductId productId) {
        lock.readLock().lock();
        try {
            List<ProductVersion> history = histories.get(productId);
            if (history == null) {
                throw new ProductNotFoundException(productId);
            }
            return List.copyOf(history);
        } finally {
            lock.readLock().unlock();
        }
    }

    private void ensureSkusAvailable(Product product) {
        Set<Sku> encountered = new HashSet<>();
        for (Variant variant : product.variants()) {
            if (!encountered.add(variant.sku())) {
                throw new DuplicateSkuException(variant.sku(), product.id());
            }
            ProductId owner = permanentSkuOwners.get(variant.sku());
            if (owner != null && !owner.equals(product.id())) {
                throw new DuplicateSkuException(variant.sku(), owner);
            }
        }
    }

    private void reserveSkus(Product product) {
        for (Variant variant : product.variants()) {
            permanentSkuOwners.put(variant.sku(), product.id());
        }
    }

    private static void verifyStableVariants(Product current, Product replacement) {
        Map<VariantId, Variant> replacementsById = replacement.variants().stream()
                .collect(Collectors.toMap(Variant::id, Function.identity()));
        for (Variant previous : current.variants()) {
            Variant next = replacementsById.get(previous.id());
            if (next == null) {
                throw new InvalidProductUpdateException(
                        current.id(),
                        "variant " + previous.id() + " cannot be removed");
            }
            if (!next.sku().equals(previous.sku())) {
                throw new InvalidProductUpdateException(
                        current.id(),
                        "SKU for variant " + previous.id() + " is immutable");
            }
        }
    }

    private static void verifyHistoryEntry(Product product, ProductVersion version) {
        if (!version.snapshot().equals(product)) {
            throw new IllegalArgumentException("history snapshot must equal the stored product");
        }
    }
}

package com.example.lld.product_catalog_service.service;

import com.example.lld.product_catalog_service.exception.CategoryNotFoundException;
import com.example.lld.product_catalog_service.exception.InvalidProductStateException;
import com.example.lld.product_catalog_service.exception.ProductNotFoundException;
import com.example.lld.product_catalog_service.exception.ProductValidationException;
import com.example.lld.product_catalog_service.exception.SkuNotFoundException;
import com.example.lld.product_catalog_service.exception.VersionConflictException;
import com.example.lld.product_catalog_service.model.Category;
import com.example.lld.product_catalog_service.model.CategoryId;
import com.example.lld.product_catalog_service.model.CategorySchema;
import com.example.lld.product_catalog_service.model.ChangeCategorySchemaCommand;
import com.example.lld.product_catalog_service.model.CreateCategoryCommand;
import com.example.lld.product_catalog_service.model.CreateProductCommand;
import com.example.lld.product_catalog_service.model.Product;
import com.example.lld.product_catalog_service.model.ProductBrowseQuery;
import com.example.lld.product_catalog_service.model.ProductChangeType;
import com.example.lld.product_catalog_service.model.ProductId;
import com.example.lld.product_catalog_service.model.ProductSchemaImpact;
import com.example.lld.product_catalog_service.model.ProductStatus;
import com.example.lld.product_catalog_service.model.ProductVersion;
import com.example.lld.product_catalog_service.model.SchemaChangeImpactReport;
import com.example.lld.product_catalog_service.model.Sku;
import com.example.lld.product_catalog_service.model.UpdateProductCommand;
import com.example.lld.product_catalog_service.model.ValidationIssue;
import com.example.lld.product_catalog_service.port.CategoryRepository;
import com.example.lld.product_catalog_service.port.ProductIdGenerator;
import com.example.lld.product_catalog_service.port.ProductRepository;
import java.time.Clock;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public final class ProductCatalogService {
    private final ProductRepository productRepository;
    private final CategoryRepository categoryRepository;
    private final ProductIdGenerator productIdGenerator;
    private final Clock clock;
    private final ProductValidator validator = new ProductValidator();
    private final ReentrantReadWriteLock catalogLock = new ReentrantReadWriteLock(true);

    public ProductCatalogService(
            ProductRepository productRepository,
            CategoryRepository categoryRepository,
            ProductIdGenerator productIdGenerator,
            Clock clock) {
        this.productRepository = Objects.requireNonNull(productRepository, "productRepository must not be null");
        this.categoryRepository = Objects.requireNonNull(categoryRepository, "categoryRepository must not be null");
        this.productIdGenerator = Objects.requireNonNull(productIdGenerator, "productIdGenerator must not be null");
        this.clock = Objects.requireNonNull(clock, "clock must not be null");
    }

    public static ProductCatalogService inMemory(ProductIdGenerator productIdGenerator, Clock clock) {
        return new ProductCatalogService(
                new InMemoryProductRepository(),
                new InMemoryCategoryRepository(),
                productIdGenerator,
                clock);
    }

    public Category createCategory(CreateCategoryCommand command) {
        Objects.requireNonNull(command, "command must not be null");
        catalogLock.writeLock().lock();
        try {
            command.parentId().ifPresent(this::requireCategory);
            Instant now = clock.instant();
            Category category = new Category(
                    command.id(),
                    command.name(),
                    command.parentId(),
                    command.localDefinitions(),
                    1,
                    now,
                    command.actor());
            return categoryRepository.insert(category);
        } finally {
            catalogLock.writeLock().unlock();
        }
    }

    public Category getCategory(CategoryId categoryId) {
        Objects.requireNonNull(categoryId, "categoryId must not be null");
        catalogLock.readLock().lock();
        try {
            return requireCategory(categoryId);
        } finally {
            catalogLock.readLock().unlock();
        }
    }

    public List<Category> childrenOf(CategoryId categoryId) {
        Objects.requireNonNull(categoryId, "categoryId must not be null");
        catalogLock.readLock().lock();
        try {
            requireCategory(categoryId);
            return categoryRepository.findAll().stream()
                    .filter(category -> category.parentId().filter(categoryId::equals).isPresent())
                    .sorted(Comparator.comparing(Category::id))
                    .toList();
        } finally {
            catalogLock.readLock().unlock();
        }
    }

    public CategorySchema effectiveSchemaFor(CategoryId categoryId) {
        Objects.requireNonNull(categoryId, "categoryId must not be null");
        catalogLock.readLock().lock();
        try {
            return effectiveSchema(categoryId);
        } finally {
            catalogLock.readLock().unlock();
        }
    }

    public Product createProduct(CreateProductCommand command) {
        Objects.requireNonNull(command, "command must not be null");
        catalogLock.writeLock().lock();
        try {
            requireCategory(command.categoryId());
            ProductId productId = Objects.requireNonNull(
                    productIdGenerator.nextProductId(),
                    "productIdGenerator returned null");
            Instant now = clock.instant();
            Product product = new Product(
                    productId,
                    command.name(),
                    command.description(),
                    command.brand(),
                    command.categoryId(),
                    command.attributes(),
                    command.variants(),
                    command.media(),
                    ProductStatus.DRAFT,
                    1,
                    now,
                    now,
                    command.actor());
            validate(product, false);
            ProductVersion version = historyEntry(product, ProductChangeType.CREATED, command.actor(), now);
            return productRepository.insert(product, version);
        } finally {
            catalogLock.writeLock().unlock();
        }
    }

    public Product updateProduct(UpdateProductCommand command) {
        Objects.requireNonNull(command, "command must not be null");
        catalogLock.writeLock().lock();
        try {
            Product current = requireProduct(command.productId());
            requireExpectedVersion(current, command.expectedVersion());
            if (current.status() == ProductStatus.ARCHIVED) {
                throw new InvalidProductStateException(current.id(), "updated", current.status());
            }
            requireCategory(command.categoryId());
            Instant now = clock.instant();
            Product revised = current.revise(
                    command.name(),
                    command.description(),
                    command.brand(),
                    command.categoryId(),
                    command.attributes(),
                    command.variants(),
                    command.media(),
                    now,
                    command.actor());
            validate(revised, revised.status() == ProductStatus.ACTIVE);
            return productRepository.replace(
                    revised,
                    command.expectedVersion(),
                    historyEntry(revised, ProductChangeType.UPDATED, command.actor(), now));
        } finally {
            catalogLock.writeLock().unlock();
        }
    }

    public Product publishProduct(ProductId productId, long expectedVersion, String actor) {
        return transition(
                productId,
                expectedVersion,
                actor,
                ProductStatus.DRAFT,
                ProductStatus.ACTIVE,
                ProductChangeType.PUBLISHED,
                true);
    }

    public Product archiveProduct(ProductId productId, long expectedVersion, String actor) {
        Objects.requireNonNull(productId, "productId must not be null");
        catalogLock.writeLock().lock();
        try {
            Product current = requireProduct(productId);
            requireExpectedVersion(current, expectedVersion);
            if (current.status() == ProductStatus.ARCHIVED) {
                throw new InvalidProductStateException(
                        productId,
                        ProductStatus.ARCHIVED,
                        ProductStatus.ARCHIVED);
            }
            return saveTransition(current, expectedVersion, actor, ProductStatus.ARCHIVED,
                    ProductChangeType.ARCHIVED, false);
        } finally {
            catalogLock.writeLock().unlock();
        }
    }

    public Product reactivateProduct(ProductId productId, long expectedVersion, String actor) {
        return transition(
                productId,
                expectedVersion,
                actor,
                ProductStatus.ARCHIVED,
                ProductStatus.ACTIVE,
                ProductChangeType.REACTIVATED,
                true);
    }

    public Product getProduct(ProductId productId) {
        Objects.requireNonNull(productId, "productId must not be null");
        catalogLock.readLock().lock();
        try {
            return requireProduct(productId);
        } finally {
            catalogLock.readLock().unlock();
        }
    }

    public Product getProductBySku(Sku sku) {
        Objects.requireNonNull(sku, "sku must not be null");
        catalogLock.readLock().lock();
        try {
            return productRepository.findBySku(sku).orElseThrow(() -> new SkuNotFoundException(sku));
        } finally {
            catalogLock.readLock().unlock();
        }
    }

    public List<ProductVersion> history(ProductId productId) {
        Objects.requireNonNull(productId, "productId must not be null");
        catalogLock.readLock().lock();
        try {
            requireProduct(productId);
            return productRepository.history(productId);
        } finally {
            catalogLock.readLock().unlock();
        }
    }

    public List<Product> browse(ProductBrowseQuery query) {
        Objects.requireNonNull(query, "query must not be null");
        catalogLock.readLock().lock();
        try {
            Set<CategoryId> categoryIds = query.categoryId()
                    .map(id -> query.includeDescendantCategories()
                            ? descendantCategoryIds(id)
                            : Set.of(requireCategory(id).id()))
                    .orElseGet(Set::of);

            return productRepository.findAll().stream()
                    .filter(product -> query.statuses().isEmpty() || query.statuses().contains(product.status()))
                    .filter(product -> categoryIds.isEmpty() || categoryIds.contains(product.categoryId()))
                    .filter(product -> query.brand()
                            .map(brand -> brand.equalsIgnoreCase(product.brand()))
                            .orElse(true))
                    .filter(product -> containsAll(product.attributes(), query.productAttributes()))
                    .filter(product -> query.variantAttributes().isEmpty()
                            || product.variants().stream().anyMatch(variant ->
                                    containsAll(variant.attributes(), query.variantAttributes())))
                    .sorted(Comparator.comparing(Product::id))
                    .toList();
        } finally {
            catalogLock.readLock().unlock();
        }
    }

    public SchemaChangeImpactReport changeCategorySchema(ChangeCategorySchemaCommand command) {
        Objects.requireNonNull(command, "command must not be null");
        catalogLock.writeLock().lock();
        try {
            Category current = requireCategory(command.categoryId());
            if (current.schemaVersion() != command.expectedSchemaVersion()) {
                throw new VersionConflictException(
                        "category schema",
                        current.id().value(),
                        command.expectedSchemaVersion(),
                        current.schemaVersion());
            }

            Set<CategoryId> dependentCategoryIds = descendantCategoryIds(current.id());
            List<Product> dependentProducts = productRepository.findAll().stream()
                    .filter(product -> dependentCategoryIds.contains(product.categoryId()))
                    .sorted(Comparator.comparing(Product::id))
                    .toList();
            Map<ProductId, List<ValidationIssue>> before = new HashMap<>();
            for (Product product : dependentProducts) {
                before.put(product.id(), validator.validate(product, effectiveSchema(product.categoryId()), true));
            }

            Instant changedAt = clock.instant();
            Category changed = current.changeSchema(command.localDefinitions(), changedAt, command.actor());
            categoryRepository.replace(changed, command.expectedSchemaVersion());

            List<ProductSchemaImpact> impacts = new ArrayList<>();
            for (Product product : dependentProducts) {
                List<ValidationIssue> after = validator.validate(
                        product,
                        effectiveSchema(product.categoryId()),
                        true);
                List<ValidationIssue> previous = before.get(product.id());
                boolean demoteFromActive = product.status() == ProductStatus.ACTIVE && !after.isEmpty();
                if (!sameIssues(previous, after) || demoteFromActive) {
                    impacts.add(new ProductSchemaImpact(
                            product.id(),
                            product.version(),
                            product.status(),
                            previous,
                            after));
                }
                if (demoteFromActive) {
                    Product demoted = product.transitionTo(
                            ProductStatus.DRAFT,
                            changedAt,
                            command.actor());
                    productRepository.replace(
                            demoted,
                            product.version(),
                            historyEntry(
                                    demoted,
                                    ProductChangeType.SCHEMA_INVALIDATED,
                                    command.actor(),
                                    changedAt));
                }
            }
            return new SchemaChangeImpactReport(
                    current.id(),
                    current.schemaVersion(),
                    changed.schemaVersion(),
                    changedAt,
                    impacts);
        } finally {
            catalogLock.writeLock().unlock();
        }
    }

    private Product transition(
            ProductId productId,
            long expectedVersion,
            String actor,
            ProductStatus requiredCurrent,
            ProductStatus target,
            ProductChangeType changeType,
            boolean validateForPublication) {
        Objects.requireNonNull(productId, "productId must not be null");
        catalogLock.writeLock().lock();
        try {
            Product current = requireProduct(productId);
            requireExpectedVersion(current, expectedVersion);
            if (current.status() != requiredCurrent) {
                throw new InvalidProductStateException(productId, current.status(), target);
            }
            return saveTransition(
                    current,
                    expectedVersion,
                    actor,
                    target,
                    changeType,
                    validateForPublication);
        } finally {
            catalogLock.writeLock().unlock();
        }
    }

    private Product saveTransition(
            Product current,
            long expectedVersion,
            String actor,
            ProductStatus target,
            ProductChangeType changeType,
            boolean validateForPublication) {
        String checkedActor = requireActor(actor);
        Instant now = clock.instant();
        Product changed = current.transitionTo(target, now, checkedActor);
        if (validateForPublication) {
            validate(changed, true);
        }
        return productRepository.replace(
                changed,
                expectedVersion,
                historyEntry(changed, changeType, checkedActor, now));
    }

    private void validate(Product product, boolean requirePublicationCompleteness) {
        List<ValidationIssue> issues = validator.validate(
                product,
                effectiveSchema(product.categoryId()),
                requirePublicationCompleteness);
        if (!issues.isEmpty()) {
            throw new ProductValidationException(product.id(), issues);
        }
    }

    private CategorySchema effectiveSchema(CategoryId categoryId) {
        List<Category> lineage = new ArrayList<>();
        Set<CategoryId> visited = new HashSet<>();
        Category cursor = requireCategory(categoryId);
        while (true) {
            if (!visited.add(cursor.id())) {
                throw new IllegalStateException("category hierarchy contains a cycle at " + cursor.id());
            }
            lineage.add(cursor);
            if (cursor.parentId().isEmpty()) {
                break;
            }
            cursor = requireCategory(cursor.parentId().orElseThrow());
        }
        Collections.reverse(lineage);
        CategorySchema schema = CategorySchema.empty();
        for (Category category : lineage) {
            schema = schema.overlay(category.localDefinitions());
        }
        return schema;
    }

    private Set<CategoryId> descendantCategoryIds(CategoryId rootId) {
        requireCategory(rootId);
        Set<CategoryId> result = new HashSet<>();
        result.add(rootId);
        List<Category> categories = categoryRepository.findAll();
        boolean expanded;
        do {
            expanded = false;
            for (Category category : categories) {
                if (category.parentId().filter(result::contains).isPresent()
                        && result.add(category.id())) {
                    expanded = true;
                }
            }
        } while (expanded);
        return Set.copyOf(result);
    }

    private Category requireCategory(CategoryId categoryId) {
        return categoryRepository.findById(categoryId)
                .orElseThrow(() -> new CategoryNotFoundException(categoryId));
    }

    private Product requireProduct(ProductId productId) {
        return productRepository.findById(productId)
                .orElseThrow(() -> new ProductNotFoundException(productId));
    }

    private static void requireExpectedVersion(Product product, long expectedVersion) {
        if (product.version() != expectedVersion) {
            throw new VersionConflictException(
                    "product",
                    product.id().value(),
                    expectedVersion,
                    product.version());
        }
    }

    private static ProductVersion historyEntry(
            Product product,
            ProductChangeType changeType,
            String actor,
            Instant recordedAt) {
        return new ProductVersion(product.version(), changeType, actor, recordedAt, product);
    }

    private static boolean containsAll(Map<?, ?> actual, Map<?, ?> expected) {
        return expected.entrySet().stream()
                .allMatch(entry -> Objects.equals(actual.get(entry.getKey()), entry.getValue()));
    }

    private static boolean sameIssues(
            List<ValidationIssue> first,
            List<ValidationIssue> second) {
        Comparator<ValidationIssue> byPathAndMessage = Comparator
                .comparing(ValidationIssue::path)
                .thenComparing(ValidationIssue::message);
        return first.stream().sorted(byPathAndMessage).toList()
                .equals(second.stream().sorted(byPathAndMessage).toList());
    }

    private static String requireActor(String actor) {
        Objects.requireNonNull(actor, "actor must not be null");
        String trimmed = actor.trim();
        if (trimmed.isEmpty()) {
            throw new IllegalArgumentException("actor must not be blank");
        }
        return trimmed;
    }
}

package com.example.lld.product_catalog_service.service;

import com.example.lld.product_catalog_service.model.AttributeDefinition;
import com.example.lld.product_catalog_service.model.AttributeKey;
import com.example.lld.product_catalog_service.model.AttributeValue;
import com.example.lld.product_catalog_service.model.CategorySchema;
import com.example.lld.product_catalog_service.model.Product;
import com.example.lld.product_catalog_service.model.Sku;
import com.example.lld.product_catalog_service.model.ValidationIssue;
import com.example.lld.product_catalog_service.model.Variant;
import com.example.lld.product_catalog_service.model.VariantId;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

final class ProductValidator {
    List<ValidationIssue> validate(
            Product product,
            CategorySchema schema,
            boolean requirePublicationCompleteness) {
        List<ValidationIssue> issues = new ArrayList<>();

        validateValues("attributes", product.attributes(), schema.productAttributes(), issues);
        if (requirePublicationCompleteness) {
            if (product.description().isBlank()) {
                issues.add(new ValidationIssue("description", "is required for publication"));
            }
            addMissingRequired(
                    "attributes",
                    product.attributes(),
                    schema.productAttributes(),
                    issues);
            if (product.variants().isEmpty()) {
                issues.add(new ValidationIssue("variants", "at least one sellable variant is required"));
            }
        }

        Set<VariantId> variantIds = new HashSet<>();
        Set<Sku> skus = new HashSet<>();
        Set<Map<AttributeKey, AttributeValue>> combinations = new HashSet<>();
        for (int index = 0; index < product.variants().size(); index++) {
            Variant variant = product.variants().get(index);
            String path = "variants[" + index + "]";
            if (!variantIds.add(variant.id())) {
                issues.add(new ValidationIssue(path + ".id", "duplicate variant id " + variant.id()));
            }
            if (!skus.add(variant.sku())) {
                issues.add(new ValidationIssue(path + ".sku", "duplicate SKU " + variant.sku()));
            }
            validateValues(
                    path + ".attributes",
                    variant.attributes(),
                    schema.variantAttributes(),
                    issues);
            if (requirePublicationCompleteness) {
                addMissingRequired(
                        path + ".attributes",
                        variant.attributes(),
                        schema.variantAttributes(),
                        issues);
            }
            if (!schema.variantAttributes().isEmpty()) {
                Map<AttributeKey, AttributeValue> combination = canonicalCombination(variant, schema);
                if (!combinations.add(combination)) {
                    issues.add(new ValidationIssue(
                            path + ".attributes",
                            "duplicates another variant attribute combination"));
                }
            }
        }
        return List.copyOf(issues);
    }

    private static void validateValues(
            String path,
            Map<AttributeKey, AttributeValue> values,
            Map<AttributeKey, AttributeDefinition> definitions,
            List<ValidationIssue> issues) {
        values.forEach((key, value) -> {
            AttributeDefinition definition = definitions.get(key);
            if (definition == null) {
                issues.add(new ValidationIssue(path + "." + key, "is not defined by the category schema"));
                return;
            }
            definition.violation(value).ifPresent(message ->
                    issues.add(new ValidationIssue(path + "." + key, message)));
        });
    }

    private static void addMissingRequired(
            String path,
            Map<AttributeKey, AttributeValue> values,
            Map<AttributeKey, AttributeDefinition> definitions,
            List<ValidationIssue> issues) {
        definitions.values().stream()
                .filter(AttributeDefinition::required)
                .filter(definition -> !values.containsKey(definition.key()))
                .forEach(definition -> issues.add(new ValidationIssue(
                        path + "." + definition.key(),
                        "required attribute is missing")));
    }

    private static Map<AttributeKey, AttributeValue> canonicalCombination(
            Variant variant,
            CategorySchema schema) {
        Map<AttributeKey, AttributeValue> combination = new TreeMap<>();
        for (AttributeKey key : schema.variantAttributes().keySet()) {
            AttributeValue value = variant.attributes().get(key);
            if (value != null) {
                combination.put(key, value);
            }
        }
        return Collections.unmodifiableMap(combination);
    }
}

"""One-hour Python core for an authoritative, versioned product catalog."""

from __future__ import annotations

from dataclasses import dataclass, field, replace
from datetime import datetime, timezone
from decimal import Decimal
from enum import Enum
from threading import RLock
from types import MappingProxyType
from typing import Callable, Mapping, Sequence, Union

AttributeValue = Union[str, int, Decimal, bool]


class AttributeType(str, Enum):
    TEXT = "text"
    INTEGER = "integer"
    DECIMAL = "decimal"
    BOOLEAN = "boolean"
    ENUM = "enum"


class AttributeScope(str, Enum):
    PRODUCT = "product"
    VARIANT = "variant"


class ProductStatus(str, Enum):
    DRAFT = "draft"
    ACTIVE = "active"
    ARCHIVED = "archived"


class ChangeType(str, Enum):
    CREATED = "created"
    UPDATED = "updated"
    PUBLISHED = "published"
    ARCHIVED = "archived"
    REACTIVATED = "reactivated"
    SCHEMA_INVALIDATED = "schema_invalidated"


class CatalogError(RuntimeError):
    pass


class VersionConflict(CatalogError):
    pass


class DuplicateSku(CatalogError):
    pass


@dataclass(frozen=True, order=True)
class ValidationIssue:
    path: str
    message: str


class ProductValidationError(CatalogError):
    def __init__(self, product_id: str, issues: Sequence[ValidationIssue]) -> None:
        super().__init__(f"product {product_id} has {len(issues)} validation issue(s)")
        self.issues = tuple(sorted(issues))


@dataclass(frozen=True)
class AttributeDefinition:
    key: str
    label: str
    value_type: AttributeType
    scope: AttributeScope
    required: bool = False
    enum_values: frozenset[str] = field(default_factory=frozenset)

    def __post_init__(self) -> None:
        if not self.key.strip() or not self.label.strip():
            raise ValueError("attribute key and label must not be blank")
        if (self.value_type is AttributeType.ENUM) != bool(self.enum_values):
            raise ValueError("exactly enum attributes must declare enum_values")

    def violation(self, value: AttributeValue) -> str | None:
        valid_type = {
            AttributeType.TEXT: type(value) is str,
            AttributeType.INTEGER: type(value) is int,
            AttributeType.DECIMAL: type(value) is Decimal,
            AttributeType.BOOLEAN: type(value) is bool,
            AttributeType.ENUM: type(value) is str,
        }[self.value_type]
        if not valid_type:
            return f"expected {self.value_type.value}"
        if self.value_type is AttributeType.ENUM and value not in self.enum_values:
            return f"must be one of {sorted(self.enum_values)}"
        return None


def _freeze(values: Mapping[str, AttributeValue]) -> Mapping[str, AttributeValue]:
    return MappingProxyType(dict(values))


@dataclass(frozen=True)
class Category:
    category_id: str
    name: str
    parent_id: str | None
    definitions: Mapping[str, AttributeDefinition]
    version: int

    def __post_init__(self) -> None:
        if not self.category_id.strip() or not self.name.strip():
            raise ValueError("category_id and name must not be blank")
        if self.version <= 0:
            raise ValueError("category version must be positive")
        object.__setattr__(self, "definitions", MappingProxyType(dict(self.definitions)))


@dataclass(frozen=True)
class Variant:
    variant_id: str
    sku: str
    attributes: Mapping[str, AttributeValue]

    def __post_init__(self) -> None:
        if not self.variant_id.strip() or not self.sku.strip():
            raise ValueError("variant_id and sku must not be blank")
        object.__setattr__(self, "attributes", _freeze(self.attributes))


@dataclass(frozen=True)
class Product:
    product_id: str
    name: str
    description: str
    brand: str
    category_id: str
    attributes: Mapping[str, AttributeValue]
    variants: tuple[Variant, ...]
    media: tuple[str, ...]
    status: ProductStatus
    version: int
    created_at: datetime
    changed_at: datetime
    actor: str

    def __post_init__(self) -> None:
        if not self.product_id.strip() or not self.category_id.strip() or not self.actor.strip():
            raise ValueError("product_id, category_id, and actor must not be blank")
        if self.version <= 0:
            raise ValueError("product version must be positive")
        object.__setattr__(self, "attributes", _freeze(self.attributes))
        object.__setattr__(self, "variants", tuple(self.variants))
        object.__setattr__(self, "media", tuple(self.media))


@dataclass(frozen=True)
class ProductVersion:
    change_type: ChangeType
    snapshot: Product


@dataclass(frozen=True)
class SchemaImpact:
    product_id: str
    previous_status: ProductStatus
    before: tuple[ValidationIssue, ...]
    after: tuple[ValidationIssue, ...]


class ProductRepository:
    """A DB adapter would replace this lock with version and unique-SKU constraints."""

    def __init__(self) -> None:
        self._products: dict[str, Product] = {}
        self._sku_owner: dict[str, str] = {}
        self._history: dict[str, list[ProductVersion]] = {}
        self._lock = RLock()

    def get(self, product_id: str) -> Product:
        with self._lock:
            if product_id not in self._products:
                raise CatalogError(f"unknown product: {product_id}")
            return self._products[product_id]

    def get_by_sku(self, sku: str) -> Product:
        with self._lock:
            owner = self._sku_owner.get(sku)
            if owner is None:
                raise CatalogError(f"unknown SKU: {sku}")
            return self._products[owner]

    def all(self) -> tuple[Product, ...]:
        with self._lock:
            return tuple(self._products.values())

    def history(self, product_id: str) -> tuple[ProductVersion, ...]:
        with self._lock:
            return tuple(self._history.get(product_id, ()))

    def save(
        self,
        product: Product,
        change_type: ChangeType,
        expected_version: int | None,
    ) -> Product:
        with self._lock:
            current = self._products.get(product.product_id)
            if expected_version is None:
                if current is not None:
                    raise CatalogError(f"duplicate product: {product.product_id}")
                if product.version != 1:
                    raise VersionConflict("a new product must start at version 1")
            elif current is None or current.version != expected_version:
                actual = current.version if current else "missing"
                raise VersionConflict(f"expected {expected_version}, actual {actual}")
            else:
                if product.version != expected_version + 1:
                    raise VersionConflict(
                        "a saved revision must increase the version by exactly one"
                    )
                old = {variant.variant_id: variant.sku for variant in current.variants}
                new = {variant.variant_id: variant.sku for variant in product.variants}
                if any(new.get(variant_id) != sku for variant_id, sku in old.items()):
                    raise CatalogError("existing variants cannot be removed or re-keyed")

            skus = [variant.sku for variant in product.variants]
            if len(skus) != len(set(skus)):
                raise DuplicateSku("a product cannot contain the same SKU twice")
            for sku in skus:
                owner = self._sku_owner.get(sku)
                if owner is not None and owner != product.product_id:
                    raise DuplicateSku(f"SKU {sku} is permanently owned by {owner}")
            for sku in skus:
                self._sku_owner[sku] = product.product_id
            self._products[product.product_id] = product
            self._history.setdefault(product.product_id, []).append(
                ProductVersion(change_type, product)
            )
            return product


class ProductCatalogService:
    def __init__(
        self,
        repository: ProductRepository,
        next_product_id: Callable[[], str],
        clock: Callable[[], datetime] = lambda: datetime.now(timezone.utc),
    ) -> None:
        self._repository = repository
        self._next_product_id = next_product_id
        self._clock = clock
        self._categories: dict[str, Category] = {}
        self._lock = RLock()

    def create_category(
        self,
        category_id: str,
        name: str,
        definitions: Sequence[AttributeDefinition],
        actor: str,
        parent_id: str | None = None,
    ) -> Category:
        if not actor.strip():
            raise ValueError("actor must not be blank")
        del actor  # an ORM/outbox adapter would persist the taxonomy audit record
        with self._lock:
            if category_id in self._categories:
                raise CatalogError(f"duplicate category: {category_id}")
            if parent_id is not None:
                self._category(parent_id)
            mapped = {definition.key: definition for definition in definitions}
            if len(mapped) != len(definitions):
                raise ValueError("duplicate attribute definition")
            category = Category(category_id, name, parent_id, mapped, 1)
            self._categories[category_id] = category
            return category

    def effective_schema(self, category_id: str) -> Mapping[str, AttributeDefinition]:
        with self._lock:
            lineage: list[Category] = []
            seen: set[str] = set()
            category = self._category(category_id)
            while True:
                if category.category_id in seen:
                    raise CatalogError("category hierarchy contains a cycle")
                seen.add(category.category_id)
                lineage.append(category)
                if category.parent_id is None:
                    break
                category = self._category(category.parent_id)
            schema: dict[str, AttributeDefinition] = {}
            for category in reversed(lineage):
                schema.update(category.definitions)
            return MappingProxyType(schema)

    def create_product(
        self,
        *,
        name: str,
        description: str,
        brand: str,
        category_id: str,
        attributes: Mapping[str, AttributeValue],
        variants: Sequence[Variant],
        media: Sequence[str],
        actor: str,
    ) -> Product:
        with self._lock:
            self._category(category_id)
            now = self._clock()
            product = Product(
                self._next_product_id(), name, description, brand, category_id,
                attributes, tuple(variants), tuple(media), ProductStatus.DRAFT,
                1, now, now, actor,
            )
            self._require_valid(product, complete=False)
            return self._repository.save(product, ChangeType.CREATED, None)

    def update_product(
        self,
        product_id: str,
        expected_version: int,
        actor: str,
        **changes: object,
    ) -> Product:
        with self._lock:
            current = self._repository.get(product_id)
            self._version(current, expected_version)
            if current.status is ProductStatus.ARCHIVED:
                raise CatalogError("an archived product cannot be edited")
            forbidden = {"product_id", "status", "version", "created_at", "changed_at", "actor"}
            if forbidden.intersection(changes):
                raise ValueError("identity, lifecycle, and audit fields cannot be patched")
            revised = replace(
                current, **changes, version=current.version + 1,
                changed_at=self._clock(), actor=actor,
            )
            self._category(revised.category_id)
            self._require_valid(revised, revised.status is ProductStatus.ACTIVE)
            return self._repository.save(revised, ChangeType.UPDATED, expected_version)

    def publish(self, product_id: str, expected_version: int, actor: str) -> Product:
        return self._transition(
            product_id, expected_version, ProductStatus.DRAFT, ProductStatus.ACTIVE,
            ChangeType.PUBLISHED, actor, validate=True,
        )

    def archive(self, product_id: str, expected_version: int, actor: str) -> Product:
        with self._lock:
            current = self._repository.get(product_id)
            if current.status is ProductStatus.ARCHIVED:
                raise CatalogError("product is already archived")
            self._version(current, expected_version)
            return self._save_transition(
                current, ProductStatus.ARCHIVED, ChangeType.ARCHIVED, actor, False
            )

    def reactivate(self, product_id: str, expected_version: int, actor: str) -> Product:
        return self._transition(
            product_id, expected_version, ProductStatus.ARCHIVED, ProductStatus.ACTIVE,
            ChangeType.REACTIVATED, actor, validate=True,
        )

    def change_category_schema(
        self,
        category_id: str,
        expected_version: int,
        definitions: Sequence[AttributeDefinition],
        actor: str,
    ) -> tuple[SchemaImpact, ...]:
        with self._lock:
            category = self._category(category_id)
            if category.version != expected_version:
                raise VersionConflict("category schema version conflict")
            mapped = {definition.key: definition for definition in definitions}
            if len(mapped) != len(definitions):
                raise ValueError("duplicate attribute definition")
            products = tuple(
                product for product in self._repository.all()
                if product.category_id in self._descendants(category_id)
            )
            before = {p.product_id: self._validate(p, complete=True) for p in products}
            self._categories[category_id] = replace(
                category, definitions=mapped, version=category.version + 1
            )
            impacts: list[SchemaImpact] = []
            for product in products:
                after = self._validate(product, complete=True)
                invalid_active = product.status is ProductStatus.ACTIVE and bool(after)
                if before[product.product_id] != after or invalid_active:
                    impacts.append(
                        SchemaImpact(product.product_id, product.status, before[product.product_id], after)
                    )
                if invalid_active:
                    self._save_transition(
                        product, ProductStatus.DRAFT, ChangeType.SCHEMA_INVALIDATED,
                        actor, False,
                    )
            return tuple(impacts)

    def get(self, product_id: str) -> Product:
        return self._repository.get(product_id)

    def get_by_sku(self, sku: str) -> Product:
        return self._repository.get_by_sku(sku)

    def history(self, product_id: str) -> tuple[ProductVersion, ...]:
        return self._repository.history(product_id)

    def active_catalog(self) -> tuple[Product, ...]:
        return tuple(sorted(
            (p for p in self._repository.all() if p.status is ProductStatus.ACTIVE),
            key=lambda product: product.product_id,
        ))

    def _transition(
        self,
        product_id: str,
        expected_version: int,
        required: ProductStatus,
        target: ProductStatus,
        change_type: ChangeType,
        actor: str,
        validate: bool,
    ) -> Product:
        with self._lock:
            current = self._repository.get(product_id)
            self._version(current, expected_version)
            if current.status is not required:
                raise CatalogError(f"cannot transition {current.status.value} to {target.value}")
            return self._save_transition(current, target, change_type, actor, validate)

    def _save_transition(
        self,
        current: Product,
        target: ProductStatus,
        change_type: ChangeType,
        actor: str,
        validate: bool,
    ) -> Product:
        changed = replace(
            current, status=target, version=current.version + 1,
            changed_at=self._clock(), actor=actor,
        )
        if validate:
            self._require_valid(changed, complete=True)
        return self._repository.save(changed, change_type, current.version)

    def _require_valid(self, product: Product, complete: bool) -> None:
        issues = self._validate(product, complete)
        if issues:
            raise ProductValidationError(product.product_id, issues)

    def _validate(self, product: Product, complete: bool) -> tuple[ValidationIssue, ...]:
        schema = self.effective_schema(product.category_id)
        product_defs = {k: d for k, d in schema.items() if d.scope is AttributeScope.PRODUCT}
        variant_defs = {k: d for k, d in schema.items() if d.scope is AttributeScope.VARIANT}
        issues: list[ValidationIssue] = []
        self._validate_values("attributes", product.attributes, product_defs, complete, issues)
        if complete:
            for path, value in (
                ("name", product.name),
                ("description", product.description),
                ("brand", product.brand),
            ):
                if not value.strip():
                    issues.append(ValidationIssue(path, "is required for publication"))
        if complete and not product.variants:
            issues.append(ValidationIssue("variants", "at least one variant is required"))

        ids: set[str] = set()
        skus: set[str] = set()
        combinations: set[tuple[tuple[str, str, str], ...]] = set()
        for index, variant in enumerate(product.variants):
            path = f"variants[{index}]"
            if variant.variant_id in ids:
                issues.append(ValidationIssue(f"{path}.variant_id", "is duplicated"))
            if variant.sku in skus:
                issues.append(ValidationIssue(f"{path}.sku", "is duplicated"))
            ids.add(variant.variant_id)
            skus.add(variant.sku)
            self._validate_values(
                f"{path}.attributes", variant.attributes, variant_defs, complete, issues
            )
            combination = tuple(sorted(
                (key, type(value).__name__, str(value))
                for key, value in variant.attributes.items() if key in variant_defs
            ))
            if variant_defs and combination in combinations:
                issues.append(ValidationIssue(f"{path}.attributes", "duplicates another variant"))
            combinations.add(combination)
        return tuple(sorted(issues))

    @staticmethod
    def _validate_values(
        path: str,
        values: Mapping[str, AttributeValue],
        definitions: Mapping[str, AttributeDefinition],
        complete: bool,
        issues: list[ValidationIssue],
    ) -> None:
        for key, value in values.items():
            definition = definitions.get(key)
            if definition is None:
                issues.append(ValidationIssue(f"{path}.{key}", "is not defined by the schema"))
            elif violation := definition.violation(value):
                issues.append(ValidationIssue(f"{path}.{key}", violation))
        if complete:
            issues.extend(
                ValidationIssue(f"{path}.{definition.key}", "required attribute is missing")
                for definition in definitions.values()
                if definition.required and definition.key not in values
            )

    def _descendants(self, root_id: str) -> set[str]:
        result = {self._category(root_id).category_id}
        while True:
            expanded = result | {
                category.category_id for category in self._categories.values()
                if category.parent_id in result
            }
            if expanded == result:
                return result
            result = expanded

    def _category(self, category_id: str) -> Category:
        if category_id not in self._categories:
            raise CatalogError(f"unknown category: {category_id}")
        return self._categories[category_id]

    @staticmethod
    def _version(product: Product, expected: int) -> None:
        if product.version != expected:
            raise VersionConflict(f"expected {expected}, actual {product.version}")

