    public String toString() {
        return name + " (" + category + ") - $" + price;
    }
}

package com.example.lld.product_search_system;

import java.util.*;
import java.util.stream.Collectors;

/**
 * Product Search Service
 *
 * Design Choices:
 * - In-memory storage with List for simplicity.
 * - Stream API for filtering and sorting.
 * - Case-insensitive name search.
 * - Tag search with contains check.
 */
public class SearchService {
    private List<Product> products;

    public SearchService() {
        this.products = new ArrayList<>();
    }

    public void addProduct(Product product) {
        products.add(product);
    }

    /**
     * Search by name (partial match, case-insensitive)
     */
    public List<Product> searchByName(String name) {
        return products.stream()
                .filter(p -> p.getName().toLowerCase().contains(name.toLowerCase()))
                .collect(Collectors.toList());
    }

    /**
     * Filter by category
     */
    public List<Product> filterByCategory(String category) {
        return products.stream()
                .filter(p -> p.getCategory().equalsIgnoreCase(category))
                .collect(Collectors.toList());
    }

    /**
     * Filter by price range
     */
    public List<Product> filterByPriceRange(double minPrice, double maxPrice) {
        return products.stream()
                .filter(p -> p.getPrice() >= minPrice && p.getPrice() <= maxPrice)
                .collect(Collectors.toList());
    }

    /**
     * Search by tags
     */
    public List<Product> searchByTag(String tag) {
        return products.stream()
                .filter(p -> p.getTags().stream()
                        .anyMatch(t -> t.equalsIgnoreCase(tag)))
                .collect(Collectors.toList());
    }

    /**
     * Sort by price
     */
    public List<Product> sortByPrice(List<Product> productList, boolean ascending) {
        return productList.stream()
                .sorted(ascending ?
                        Comparator.comparingDouble(Product::getPrice) :
                        Comparator.comparingDouble(Product::getPrice).reversed())
                .collect(Collectors.toList());
    }

    /**
     * Combined search with multiple filters
     */
    public List<Product> advancedSearch(String name, String category,
                                      Double minPrice, Double maxPrice,
                                      String tag, String sortBy) {
        List<Product> results = new ArrayList<>(products);

        if (name != null && !name.isEmpty()) {
            results = results.stream()
                    .filter(p -> p.getName().toLowerCase().contains(name.toLowerCase()))
                    .collect(Collectors.toList());
        }

        if (category != null && !category.isEmpty()) {
            results = results.stream()
                    .filter(p -> p.getCategory().equalsIgnoreCase(category))
                    .collect(Collectors.toList());
        }

        if (minPrice != null && maxPrice != null) {
            results = results.stream()
                    .filter(p -> p.getPrice() >= minPrice && p.getPrice() <= maxPrice)
                    .collect(Collectors.toList());
        }

        if (tag != null && !tag.isEmpty()) {
            results = results.stream()
                    .filter(p -> p.getTags().stream()
                            .anyMatch(t -> t.equalsIgnoreCase(tag)))
                    .collect(Collectors.toList());
        }

        if ("price".equalsIgnoreCase(sortBy)) {
            results = sortByPrice(results, true);
        }

        return results;
    }
}

"""Thread-safe, interview-sized rate limiter with pluggable policies."""

from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass
from enum import Enum
from threading import Lock, RLock
from time import monotonic_ns
from typing import Callable, Union


class PolicyType(str, Enum):
    TOKEN_BUCKET = "token_bucket"
    FIXED_WINDOW = "fixed_window"


@dataclass(frozen=True)
class RateLimitRule:
    rule_id: str
    capacity: int
    period_ns: int
    policy_type: PolicyType
    version: int = 1
    burst_allowance: int = 0

    def __post_init__(self) -> None:
        if not self.rule_id.strip():
            raise ValueError("rule_id must not be blank")
        if self.capacity <= 0 or self.period_ns <= 0:
            raise ValueError("capacity and period_ns must be positive")
        if self.burst_allowance < 0 or self.version <= 0:
            raise ValueError("burst_allowance must be non-negative and version positive")

    @property
    def maximum_balance(self) -> int:
        return self.capacity + self.burst_allowance


@dataclass(frozen=True)
class RateLimitKey:
    tenant: str
    principal: str
    endpoint: str

    def __post_init__(self) -> None:
        if not all(value.strip() for value in (self.tenant, self.principal, self.endpoint)):
            raise ValueError("rate-limit key parts must not be blank")


@dataclass(frozen=True)
class RateLimitRequest:
    rule_id: str
    key: RateLimitKey
    cost: int = 1


@dataclass(frozen=True)
class RateLimitDecision:
    allowed: bool
    remaining: int
    retry_after_ns: int
    reset_after_ns: int
    rule_version: int
    reason: str


class ManualClock:
    """Deterministic monotonic clock used by examples and tests."""

    def __init__(self, initial_ns: int = 0) -> None:
        self._now_ns = initial_ns
        self._lock = Lock()

    def now_ns(self) -> int:
        with self._lock:
            return self._now_ns

    def advance(self, nanoseconds: int) -> None:
        if nanoseconds < 0:
            raise ValueError("a monotonic clock cannot move backwards")
        with self._lock:
            self._now_ns += nanoseconds


@dataclass
class _TokenBucketState:
    credits: int
    last_refill_ns: int


@dataclass
class _FixedWindowState:
    used: int
    window_start_ns: int


PolicyState = Union[_TokenBucketState, _FixedWindowState]


class RateLimitPolicy(ABC):
    @abstractmethod
    def initial_state(self, rule: RateLimitRule, now_ns: int) -> PolicyState:
        raise NotImplementedError

    @abstractmethod
    def evaluate(
        self,
        rule: RateLimitRule,
        state: PolicyState,
        cost: int,
        now_ns: int,
    ) -> tuple[PolicyState, RateLimitDecision]:
        raise NotImplementedError


class TokenBucketPolicy(RateLimitPolicy):
    """Integer token-nanosecond credits avoid floating-point refill drift."""

    def initial_state(self, rule: RateLimitRule, now_ns: int) -> PolicyState:
        return _TokenBucketState(rule.maximum_balance * rule.period_ns, now_ns)

    def evaluate(
        self,
        rule: RateLimitRule,
        state: PolicyState,
        cost: int,
        now_ns: int,
    ) -> tuple[PolicyState, RateLimitDecision]:
        if not isinstance(state, _TokenBucketState):
            raise TypeError("token bucket received incompatible state")
        elapsed = max(0, now_ns - state.last_refill_ns)
        cap = rule.maximum_balance * rule.period_ns
        credits = min(cap, state.credits + elapsed * rule.capacity)
        required = cost * rule.period_ns
        allowed = credits >= required
        if allowed:
            credits -= required

        remaining = credits // rule.period_ns
        missing = max(0, required - credits)
        retry_after = 0 if allowed else (missing + rule.capacity - 1) // rule.capacity
        full_missing = max(0, cap - credits)
        reset_after = (full_missing + rule.capacity - 1) // rule.capacity
        decision = RateLimitDecision(
            allowed=allowed,
            remaining=remaining,
            retry_after_ns=retry_after,
            reset_after_ns=reset_after,
            rule_version=rule.version,
            reason="allowed" if allowed else "quota_exhausted",
        )
        return _TokenBucketState(credits, now_ns), decision


class FixedWindowPolicy(RateLimitPolicy):
    def initial_state(self, rule: RateLimitRule, now_ns: int) -> PolicyState:
        return _FixedWindowState(0, now_ns)

    def evaluate(
        self,
        rule: RateLimitRule,
        state: PolicyState,
        cost: int,
        now_ns: int,
    ) -> tuple[PolicyState, RateLimitDecision]:
        if not isinstance(state, _FixedWindowState):
            raise TypeError("fixed window received incompatible state")
        elapsed = max(0, now_ns - state.window_start_ns)
        if elapsed >= rule.period_ns:
            skipped = elapsed // rule.period_ns
            state = _FixedWindowState(0, state.window_start_ns + skipped * rule.period_ns)
        limit = rule.maximum_balance
        allowed = state.used + cost <= limit
        used = state.used + cost if allowed else state.used
        until_reset = max(0, state.window_start_ns + rule.period_ns - now_ns)
        decision = RateLimitDecision(
            allowed=allowed,
            remaining=limit - used,
            retry_after_ns=0 if allowed else until_reset,
            reset_after_ns=until_reset,
            rule_version=rule.version,
            reason="allowed" if allowed else "quota_exhausted",
        )
        return _FixedWindowState(used, state.window_start_ns), decision


@dataclass
class _Cell:
    rule_version: int
    state: PolicyState
    last_seen_ns: int
    lock: RLock


class RateLimiter:
    """Coordinator: configuration, per-key cells, atomic decisions, and cleanup."""

    def __init__(self, clock: Callable[[], int] = monotonic_ns) -> None:
        self._clock = clock
        self._rules: dict[str, RateLimitRule] = {}
        self._cells: dict[tuple[str, RateLimitKey], _Cell] = {}
        self._policies: dict[PolicyType, RateLimitPolicy] = {
            PolicyType.TOKEN_BUCKET: TokenBucketPolicy(),
            PolicyType.FIXED_WINDOW: FixedWindowPolicy(),
        }
        self._registry_lock = RLock()

    def register_rule(self, rule: RateLimitRule) -> None:
        with self._registry_lock:
            if rule.rule_id in self._rules:
                raise ValueError(f"duplicate rule: {rule.rule_id}")
            self._rules[rule.rule_id] = rule

    def replace_rule(self, rule_id: str, expected_version: int, replacement: RateLimitRule) -> None:
        if rule_id != replacement.rule_id:
            raise ValueError("replacement must preserve rule_id")
        with self._registry_lock:
            current = self._rules.get(rule_id)
            if current is None:
                raise KeyError(f"unknown rule: {rule_id}")
            if current.version != expected_version:
                raise ValueError(
                    f"rule version conflict: expected {expected_version}, actual {current.version}"
                )
            if replacement.version != expected_version + 1:
                raise ValueError("replacement version must increase by exactly one")
            self._rules[rule_id] = replacement

    def allow(self, request: RateLimitRequest) -> RateLimitDecision:
        cell_key = (request.rule_id, request.key)
        while True:
            now_ns = self._clock()
            with self._registry_lock:
                rule = self._rules.get(request.rule_id)
                if rule is None:
                    raise KeyError(f"unknown rule: {request.rule_id}")
                if request.cost <= 0 or request.cost > rule.maximum_balance:
                    raise ValueError(
                        "cost must be positive and no greater than maximum balance"
                    )
                policy = self._policies[rule.policy_type]
                cell = self._cells.get(cell_key)
                if cell is None:
                    cell = _Cell(
                        rule_version=rule.version,
                        state=policy.initial_state(rule, now_ns),
                        last_seen_ns=now_ns,
                        lock=RLock(),
                    )
                    self._cells[cell_key] = cell

            with cell.lock:
                # Eviction may have removed the resolved cell while this caller was
                # waiting for its lock. Never spend from that orphan: retry lookup.
                with self._registry_lock:
                    if self._cells.get(cell_key) is not cell:
                        continue
                    # Re-resolve configuration at the mutation point so a caller
                    # cannot reset a cell back to an older rule after replacement.
                    rule = self._rules[request.rule_id]
                    if request.cost > rule.maximum_balance:
                        raise ValueError(
                            "cost must be positive and no greater than maximum balance"
                        )
                    policy = self._policies[rule.policy_type]
                # Sample elapsed time at the serialized mutation point. Sampling
                # before a contended lock can make last_seen/refill move backwards.
                now_ns = max(self._clock(), cell.last_seen_ns)
                if cell.rule_version != rule.version:
                    cell.rule_version = rule.version
                    cell.state = policy.initial_state(rule, now_ns)
                cell.state, decision = policy.evaluate(
                    rule, cell.state, request.cost, now_ns
                )
                cell.last_seen_ns = now_ns
                return decision

    def evict_idle(self, idle_for_ns: int) -> int:
        if idle_for_ns < 0:
            raise ValueError("idle_for_ns must be non-negative")
        now_ns = self._clock()
        with self._registry_lock:
            candidates = tuple(self._cells.items())

        evicted = 0
        for key, cell in candidates:
            # Do not hold the registry lock while waiting for a hot cell. The
            # identity check below makes the optimistic candidate snapshot safe.
            with cell.lock:
                with self._registry_lock:
                    if (
                        self._cells.get(key) is cell
                        and now_ns - cell.last_seen_ns >= idle_for_ns
                    ):
                        del self._cells[key]
                        evicted += 1
        return evicted

package com.example.lld.rate_limiter;

import com.example.lld.rate_limiter.domain.PolicyType;
import com.example.lld.rate_limiter.domain.RateLimitDecision;
import com.example.lld.rate_limiter.domain.RateLimitKey;
import com.example.lld.rate_limiter.domain.RateLimitRequest;
import com.example.lld.rate_limiter.domain.RateLimitRule;
import com.example.lld.rate_limiter.exception.InvalidRateLimitRuleException;
import com.example.lld.rate_limiter.service.RateLimiter;
import com.example.lld.rate_limiter.time.ManualMonotonicClock;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

/** Runnable deterministic checks, including a real concurrent final-token race. */
public final class Demo {
    private Demo() {}

    public static void main(String[] args) throws InterruptedException, ExecutionException {
        ManualMonotonicClock clock = new ManualMonotonicClock();
        RateLimiter limiter = RateLimiter.withStandardPolicies(clock);

        tokenBucketExhaustionAndRefillBoundary(limiter, clock);
        independentKeys(limiter);
        fixedWindowBoundary(limiter, clock);
        concurrentFinalTokenRace(limiter);
        runtimeRuleReset(limiter);
        idleEviction();
        invalidConfiguration();

        System.out.println("All rate limiter scenarios passed.");
    }

    private static void tokenBucketExhaustionAndRefillBoundary(
            RateLimiter limiter, ManualMonotonicClock clock) {
        limiter.registerRule(new RateLimitRule(
                "api-token", 2, Duration.ofSeconds(10), 0, PolicyType.TOKEN_BUCKET));
        RateLimitKey alice = RateLimitKey.of("user", "alice");
        check(one(limiter, "api-token", alice).allowed(), "first token rejected");
        check(one(limiter, "api-token", alice).allowed(), "second token rejected");
        RateLimitDecision denied = one(limiter, "api-token", alice);
        check(!denied.allowed(), "empty bucket allowed request");
        check(denied.remaining() == 0, "remaining became negative");
        check(denied.retryAfter().equals(Duration.ofSeconds(5)), "wrong retry boundary");

        clock.advance(Duration.ofSeconds(5));
        RateLimitDecision exactBoundary = one(limiter, "api-token", alice);
        check(exactBoundary.allowed(), "request at exact refill boundary was rejected");
        System.out.println("token bucket exhaustion: retry-after=5s; exact refill boundary allowed");
    }

    private static void independentKeys(RateLimiter limiter) {
        RateLimitDecision bob = one(limiter, "api-token", RateLimitKey.of("user", "bob"));
        check(bob.allowed() && bob.remaining() == 1, "unrelated key shared state");
        System.out.println("independent key state: verified");
    }

    private static void fixedWindowBoundary(
            RateLimiter limiter, ManualMonotonicClock clock) {
        limiter.registerRule(new RateLimitRule(
                "login-window", 2, Duration.ofSeconds(10), 0, PolicyType.FIXED_WINDOW));
        RateLimitKey ip = RateLimitKey.of("ip", "203.0.113.7");
        check(one(limiter, "login-window", ip).allowed(), "fixed window request 1 failed");
        check(one(limiter, "login-window", ip).allowed(), "fixed window request 2 failed");
        check(!one(limiter, "login-window", ip).allowed(), "fixed window exceeded limit");
        clock.advance(Duration.ofSeconds(10));
        check(one(limiter, "login-window", ip).allowed(), "exact window boundary did not reset");
        System.out.println("fixed window: exact reset boundary starts the new window");
    }

    private static void concurrentFinalTokenRace(RateLimiter limiter)
            throws InterruptedException, ExecutionException {
        limiter.registerRule(new RateLimitRule(
                "race", 2, Duration.ofHours(1), 0, PolicyType.TOKEN_BUCKET));
        RateLimitKey key = RateLimitKey.of("tenant", "race-tenant");
        check(one(limiter, "race", key).allowed(), "could not reserve first race token");

        int callers = 16;
        ExecutorService pool = Executors.newFixedThreadPool(callers);
        CountDownLatch ready = new CountDownLatch(callers);
        CountDownLatch start = new CountDownLatch(1);
        List<Future<Boolean>> results = new ArrayList<>();
        try {
            for (int index = 0; index < callers; index++) {
                results.add(pool.submit(() -> {
                    ready.countDown();
                    start.await();
                    return one(limiter, "race", key).allowed();
                }));
            }
            check(ready.await(5, TimeUnit.SECONDS), "race workers did not become ready");
            start.countDown();
            int allowed = 0;
            for (Future<Boolean> result : results) {
                if (result.get()) {
                    allowed++;
                }
            }
            check(allowed == 1, "expected exactly one final-token winner, got " + allowed);
        } finally {
            start.countDown();
            pool.shutdown();
            check(pool.awaitTermination(5, TimeUnit.SECONDS), "race pool did not terminate");
        }
        System.out.println("concurrent final-token race: exactly 1 of 16 allowed");
    }

    private static void runtimeRuleReset(RateLimiter limiter) {
        RateLimitKey key = RateLimitKey.of("api-key", "runtime-client");
        limiter.registerRule(new RateLimitRule(
                "runtime", 1, Duration.ofMinutes(1), 0, PolicyType.TOKEN_BUCKET));
        check(one(limiter, "runtime", key).allowed(), "runtime initial request failed");
        check(!one(limiter, "runtime", key).allowed(), "runtime rule was not exhausted");
        long version = limiter.updateRule(new RateLimitRule(
                "runtime", 3, Duration.ofMinutes(1), 0, PolicyType.TOKEN_BUCKET));
        RateLimitDecision afterUpdate = one(limiter, "runtime", key);
        check(version == 2 && afterUpdate.ruleVersion() == 2, "rule version did not advance");
        check(afterUpdate.allowed() && afterUpdate.remaining() == 2, "updated rule did not reset");
        System.out.println("runtime update: version 2 lazily reset existing key state");
    }

    private static void idleEviction() {
        ManualMonotonicClock clock = new ManualMonotonicClock();
        RateLimiter limiter = RateLimiter.withStandardPolicies(clock);
        limiter.registerRule(new RateLimitRule(
                "eviction", 100, Duration.ofSeconds(1), 0, PolicyType.TOKEN_BUCKET));
        RateLimitKey idle = RateLimitKey.of("user", "idle");
        RateLimitKey active = RateLimitKey.of("user", "active");
        one(limiter, "eviction", idle);
        one(limiter, "eviction", active);
        clock.advance(Duration.ofSeconds(30));
        one(limiter, "eviction", active);
        clock.advance(Duration.ofSeconds(40));
        int evicted = limiter.evictIdle(Duration.ofSeconds(60));
        check(evicted == 1 && limiter.trackedKeyCount() == 1, "idle cleanup removed wrong cells");
        check(one(limiter, "eviction", active).allowed(), "cleanup changed active-key behaviour");
        System.out.println("idle eviction: idle removed, active retained");
    }

    private static void invalidConfiguration() {
        boolean rejected = false;
        try {
            new RateLimitRule(
                    "invalid", 0, Duration.ofSeconds(1), 0, PolicyType.TOKEN_BUCKET);
        } catch (InvalidRateLimitRuleException expected) {
            rejected = true;
        }
        check(rejected, "zero capacity configuration was accepted");
        System.out.println("invalid configuration: rejected");
    }

    private static RateLimitDecision one(
            RateLimiter limiter, String ruleId, RateLimitKey key) {
        return limiter.decide(RateLimitRequest.one(ruleId, key));
    }

    private static void check(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }
}

