package com.example.lld.warehouse_fulfilment_domain.model;

import com.example.lld.warehouse_fulfilment_domain.exception.InvalidStateException;

/** Immutable line counters guarded by fulfilment quantity invariants. */
public record FulfilmentLine(
        String orderLineId,
        String sku,
        int requestedQuantity,
        int allocatedQuantity,
        int pickedQuantity,
        int packedQuantity,
        int shippedQuantity,
        int cancelledQuantity) {

    public FulfilmentLine {
        if (orderLineId == null || orderLineId.isBlank() || sku == null || sku.isBlank()) {
            throw new IllegalArgumentException("orderLineId and sku must not be blank");
        }
        if (requestedQuantity <= 0
                || allocatedQuantity < 0
                || pickedQuantity < 0
                || packedQuantity < 0
                || shippedQuantity < 0
                || cancelledQuantity < 0
                || shippedQuantity > packedQuantity
                || packedQuantity > pickedQuantity
                || pickedQuantity > allocatedQuantity
                || allocatedQuantity + cancelledQuantity > requestedQuantity) {
            throw new IllegalArgumentException("fulfilment line quantity invariant violated");
        }
    }

    public static FulfilmentLine from(OrderLineDemand demand) {
        return new FulfilmentLine(
                demand.orderLineId(), demand.sku(), demand.quantity(), 0, 0, 0, 0, 0);
    }

    public FulfilmentLine allocate(int quantity) {
        if (quantity <= 0 || allocatedQuantity + cancelledQuantity + quantity > requestedQuantity) {
            throw invalid("allocate", quantity);
        }
        return copy(allocatedQuantity + quantity, pickedQuantity, packedQuantity,
                shippedQuantity, cancelledQuantity);
    }

    public FulfilmentLine recordPick(int quantity) {
        if (quantity <= 0 || pickedQuantity + quantity > allocatedQuantity) {
            throw invalid("pick", quantity);
        }
        return copy(allocatedQuantity, pickedQuantity + quantity, packedQuantity,
                shippedQuantity, cancelledQuantity);
    }

    /** Removes the unpicked part of a short allocation before it is reallocated. */
    public FulfilmentLine removeShortAllocation(int quantity) {
        if (quantity <= 0 || allocatedQuantity - quantity < pickedQuantity) {
            throw invalid("remove short allocation", quantity);
        }
        return copy(allocatedQuantity - quantity, pickedQuantity, packedQuantity,
                shippedQuantity, cancelledQuantity);
    }

    public FulfilmentLine recordPack(int quantity) {
        if (quantity <= 0 || packedQuantity + quantity > pickedQuantity) {
            throw invalid("pack", quantity);
        }
        return copy(allocatedQuantity, pickedQuantity, packedQuantity + quantity,
                shippedQuantity, cancelledQuantity);
    }

    public FulfilmentLine recordShipment(int quantity) {
        if (quantity <= 0 || shippedQuantity + quantity > packedQuantity) {
            throw invalid("ship", quantity);
        }
        return copy(allocatedQuantity, pickedQuantity, packedQuantity,
                shippedQuantity + quantity, cancelledQuantity);
    }

    public FulfilmentLine cancelUnpicked() {
        if (pickedQuantity > 0) {
            throw new InvalidStateException(
                    "Line " + orderLineId + " has picked stock and cannot be cancelled");
        }
        return copy(0, 0, 0, 0, requestedQuantity);
    }

    public int remainingToAllocate() {
        return requestedQuantity - allocatedQuantity - cancelledQuantity;
    }

    public int unpackedQuantity() {
        return pickedQuantity - packedQuantity;
    }

    public int unshippedQuantity() {
        return packedQuantity - shippedQuantity;
    }

    private FulfilmentLine copy(
            int allocated, int picked, int packed, int shipped, int cancelled) {
        return new FulfilmentLine(
                orderLineId, sku, requestedQuantity, allocated, picked, packed, shipped,
                cancelled);
    }

    private InvalidStateException invalid(String action, int quantity) {
        return new InvalidStateException(
                "Cannot " + action + " " + quantity + " unit(s) for line " + orderLineId);
    }
}

package com.example.lld.warehouse_fulfilment_domain.model;

import com.example.lld.warehouse_fulfilment_domain.exception.InvalidStateException;

import java.time.Instant;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;

/** Immutable aggregate summary; task, package, and shipment IDs point to immutable snapshots. */
public final class FulfilmentOrder {
    private final String fulfilmentId;
    private final String externalOrderId;
    private final Destination destination;
    private final Instant createdAt;
    private final FulfilmentStatus status;
    private final List<FulfilmentLine> lines;
    private final List<String> pickTaskIds;
    private final List<String> packageIds;
    private final List<String> shipmentIds;
    private final List<AuditEntry> auditTrail;

    private FulfilmentOrder(
            String fulfilmentId,
            String externalOrderId,
            Destination destination,
            Instant createdAt,
            FulfilmentStatus status,
            List<FulfilmentLine> lines,
            List<String> pickTaskIds,
            List<String> packageIds,
            List<String> shipmentIds,
            List<AuditEntry> auditTrail) {
        this.fulfilmentId = requireText(fulfilmentId, "fulfilmentId");
        this.externalOrderId = requireText(externalOrderId, "externalOrderId");
        this.destination = Objects.requireNonNull(destination, "destination");
        this.createdAt = Objects.requireNonNull(createdAt, "createdAt");
        this.status = Objects.requireNonNull(status, "status");
        this.lines = List.copyOf(lines);
        this.pickTaskIds = distinctCopy(pickTaskIds, "pick task");
        this.packageIds = distinctCopy(packageIds, "package");
        this.shipmentIds = distinctCopy(shipmentIds, "shipment");
        this.auditTrail = List.copyOf(auditTrail);
        if (this.lines.isEmpty()) {
            throw new IllegalArgumentException("a fulfilment order requires lines");
        }
        Set<String> lineIds = new HashSet<>();
        if (this.lines.stream().anyMatch(line -> !lineIds.add(line.orderLineId()))) {
            throw new IllegalArgumentException("order-line IDs must be unique");
        }
    }

    public static FulfilmentOrder received(
            String fulfilmentId,
            String externalOrderId,
            Destination destination,
            List<FulfilmentLine> lines,
            Instant createdAt,
            AuditEntry audit) {
        return new FulfilmentOrder(
                fulfilmentId, externalOrderId, destination, createdAt,
                FulfilmentStatus.RECEIVED, lines, List.of(), List.of(), List.of(),
                List.of(audit));
    }

    public FulfilmentOrder addTasks(
            List<String> newTaskIds,
            List<FulfilmentLine> updatedLines,
            FulfilmentStatus nextStatus,
            AuditEntry audit) {
        List<String> tasks = new ArrayList<>(pickTaskIds);
        tasks.addAll(newTaskIds);
        return evolve(nextStatus, updatedLines, tasks, packageIds, shipmentIds, audit);
    }

    public FulfilmentOrder updateLine(
            FulfilmentLine updatedLine,
            FulfilmentStatus nextStatus,
            AuditEntry audit) {
        List<FulfilmentLine> updated = new ArrayList<>(lines.size());
        boolean found = false;
        for (FulfilmentLine line : lines) {
            if (line.orderLineId().equals(updatedLine.orderLineId())) {
                updated.add(updatedLine);
                found = true;
            } else {
                updated.add(line);
            }
        }
        if (!found) {
            throw new IllegalArgumentException("Unknown order line: " + updatedLine.orderLineId());
        }
        return evolve(nextStatus, updated, pickTaskIds, packageIds, shipmentIds, audit);
    }

    public FulfilmentOrder updateLines(
            List<FulfilmentLine> updatedLines,
            FulfilmentStatus nextStatus,
            AuditEntry audit) {
        return evolve(nextStatus, updatedLines, pickTaskIds, packageIds, shipmentIds, audit);
    }

    public FulfilmentOrder addPackage(String packageId, AuditEntry audit) {
        List<String> packages = new ArrayList<>(packageIds);
        packages.add(packageId);
        return evolve(status, lines, pickTaskIds, packages, shipmentIds, audit);
    }

    public FulfilmentOrder addShipment(
            String shipmentId,
            List<FulfilmentLine> updatedLines,
            FulfilmentStatus nextStatus,
            AuditEntry audit) {
        List<String> shipments = new ArrayList<>(shipmentIds);
        shipments.add(shipmentId);
        return evolve(nextStatus, updatedLines, pickTaskIds, packageIds, shipments, audit);
    }

    public FulfilmentOrder transition(FulfilmentStatus nextStatus, AuditEntry audit) {
        return evolve(nextStatus, lines, pickTaskIds, packageIds, shipmentIds, audit);
    }

    public String fulfilmentId() {
        return fulfilmentId;
    }

    public String externalOrderId() {
        return externalOrderId;
    }

    public Destination destination() {
        return destination;
    }

    public Instant createdAt() {
        return createdAt;
    }

    public FulfilmentStatus status() {
        return status;
    }

    public List<FulfilmentLine> lines() {
        return lines;
    }

    public List<String> pickTaskIds() {
        return pickTaskIds;
    }

    public List<String> packageIds() {
        return packageIds;
    }

    public List<String> shipmentIds() {
        return shipmentIds;
    }

    public List<AuditEntry> auditTrail() {
        return auditTrail;
    }

    public FulfilmentLine line(String orderLineId) {
        return lines.stream()
                .filter(line -> line.orderLineId().equals(orderLineId))
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException(
                        "Unknown order line: " + orderLineId));
    }

    private FulfilmentOrder evolve(
            FulfilmentStatus nextStatus,
            List<FulfilmentLine> nextLines,
            List<String> nextTaskIds,
            List<String> nextPackageIds,
            List<String> nextShipmentIds,
            AuditEntry audit) {
        if (!transitionAllowed(status, nextStatus)) {
            throw new InvalidStateException(
                    "Fulfilment " + fulfilmentId + " cannot transition from " + status
                            + " to " + nextStatus);
        }
        List<AuditEntry> history = new ArrayList<>(auditTrail);
        history.add(audit);
        return new FulfilmentOrder(
                fulfilmentId, externalOrderId, destination, createdAt, nextStatus,
                nextLines, nextTaskIds, nextPackageIds, nextShipmentIds, history);
    }

    private static boolean transitionAllowed(
            FulfilmentStatus from, FulfilmentStatus to) {
        if (from == to) {
            return true;
        }
        return switch (from) {
            case RECEIVED -> to == FulfilmentStatus.ALLOCATED
                    || to == FulfilmentStatus.CANCELLED
                    || to == FulfilmentStatus.EXCEPTION;
            case ALLOCATED -> to == FulfilmentStatus.PICKING
                    || to == FulfilmentStatus.PICKED
                    || to == FulfilmentStatus.CANCELLED
                    || to == FulfilmentStatus.EXCEPTION;
            case PICKING -> to == FulfilmentStatus.ALLOCATED
                    || to == FulfilmentStatus.PICKED
                    || to == FulfilmentStatus.CANCELLED
                    || to == FulfilmentStatus.EXCEPTION;
            case PICKED -> to == FulfilmentStatus.PACKED
                    || to == FulfilmentStatus.EXCEPTION;
            case PACKED -> to == FulfilmentStatus.PARTIALLY_SHIPPED
                    || to == FulfilmentStatus.SHIPPED;
            case PARTIALLY_SHIPPED -> to == FulfilmentStatus.SHIPPED;
            case EXCEPTION -> to == FulfilmentStatus.ALLOCATED
                    || to == FulfilmentStatus.PICKING
                    || to == FulfilmentStatus.CANCELLED;
            case SHIPPED, CANCELLED -> false;
        };
    }

    private static List<String> distinctCopy(List<String> values, String label) {
        List<String> result = List.copyOf(values);
        if (new HashSet<>(result).size() != result.size()) {
            throw new IllegalArgumentException(label + " IDs must be unique");
        }
        return result;
    }

    private static String requireText(String value, String field) {
        if (value == null || value.isBlank()) {
            throw new IllegalArgumentException(field + " must not be blank");
        }
        return value;
    }

    @Override
    public String toString() {
        return "FulfilmentOrder{" + fulfilmentId + ", externalOrder=" + externalOrderId
                + ", status=" + status + ", tasks=" + pickTaskIds.size()
                + ", packages=" + packageIds.size() + '}';
    }
}

package com.example.lld.warehouse_fulfilment_domain.model;

import com.example.lld.warehouse_fulfilment_domain.exception.InvalidScanException;
import com.example.lld.warehouse_fulfilment_domain.exception.InvalidStateException;

import java.util.ArrayList;
import java.util.List;

/** Immutable physical package and exact order-line contents. */
public record FulfilmentPackage(
        String packageId,
        String fulfilmentId,
        String warehouseId,
        Status status,
        List<PackageContent> contents,
        int weightGrams,
        String shipmentId) {

    public enum Status {
        OPEN,
        SEALED,
        SHIPPED,
        CANCELLED
    }

    public FulfilmentPackage {
        if (packageId == null || packageId.isBlank()
                || fulfilmentId == null || fulfilmentId.isBlank()
                || warehouseId == null || warehouseId.isBlank()) {
            throw new IllegalArgumentException("package identifiers must not be blank");
        }
        if (status == null || weightGrams < 0) {
            throw new IllegalArgumentException("valid package status and weight are required");
        }
        contents = List.copyOf(contents);
        if (status == Status.OPEN && (weightGrams != 0 || shipmentId != null)) {
            throw new IllegalArgumentException("open package cannot have weight or shipment");
        }
        if ((status == Status.SEALED || status == Status.SHIPPED)
                && (contents.isEmpty() || weightGrams <= 0)) {
            throw new IllegalArgumentException("sealed/shipped package needs contents and weight");
        }
        if (status == Status.SHIPPED && (shipmentId == null || shipmentId.isBlank())) {
            throw new IllegalArgumentException("shipped package requires shipmentId");
        }
    }

    public static FulfilmentPackage open(
            String packageId, String fulfilmentId, String warehouseId) {
        return new FulfilmentPackage(
                packageId, fulfilmentId, warehouseId, Status.OPEN, List.of(), 0, null);
    }

    public FulfilmentPackage addContent(String orderLineId, String sku, int quantity) {
        if (status != Status.OPEN) {
            throw new InvalidScanException("Package " + packageId + " is not open");
        }
        if (quantity <= 0) {
            throw new InvalidScanException("Package scan quantity must be positive");
        }
        List<PackageContent> updated = new ArrayList<>();
        boolean merged = false;
        for (PackageContent content : contents) {
            if (content.orderLineId().equals(orderLineId)) {
                if (!content.sku().equals(sku)) {
                    throw new InvalidScanException("SKU does not match the package line");
                }
                updated.add(new PackageContent(
                        orderLineId, sku, Math.addExact(content.quantity(), quantity)));
                merged = true;
            } else {
                updated.add(content);
            }
        }
        if (!merged) {
            updated.add(new PackageContent(orderLineId, sku, quantity));
        }
        return new FulfilmentPackage(
                packageId, fulfilmentId, warehouseId, status, updated, 0, null);
    }

    public FulfilmentPackage seal(int finalWeightGrams) {
        if (status != Status.OPEN || contents.isEmpty() || finalWeightGrams <= 0) {
            throw new InvalidStateException(
                    "Package " + packageId + " must be non-empty and open before sealing");
        }
        return new FulfilmentPackage(
                packageId, fulfilmentId, warehouseId, Status.SEALED, contents,
                finalWeightGrams, null);
    }

    public FulfilmentPackage markShipped(String confirmedShipmentId) {
        if (status != Status.SEALED) {
            throw new InvalidStateException(
                    "Package " + packageId + " cannot ship from " + status);
        }
        return new FulfilmentPackage(
                packageId, fulfilmentId, warehouseId, Status.SHIPPED, contents,
                weightGrams, confirmedShipmentId);
    }

    public FulfilmentPackage cancelEmpty() {
        if (status != Status.OPEN || !contents.isEmpty()) {
            throw new InvalidStateException("Only an empty open package can be cancelled");
        }
        return new FulfilmentPackage(
                packageId, fulfilmentId, warehouseId, Status.CANCELLED, contents, 0, null);
    }
}

